static volatile UInt32 gTvqmV35Observed = 0;
static volatile UInt32 gTvqmV35WouldPermit = 0;
static volatile UInt32 gTvqmV35WouldStop = 0;
static volatile UInt32 gTvqmV35WouldNoSubmission = 0;
