/* V36: immutable first snapshots from the existing V35 observational decision.
 * Each state: 0 unclaimed, 1 writing, 2 complete. Only a complete record is
 * valid; readers never infer ownership from these host-only snapshots. */
struct TvqmV36FirstObservation {
    volatile UInt32 state;
    volatile UInt32 qid;
    volatile UInt32 tid;
    volatile UInt32 generation;
    volatile UInt32 occupiedBits;
    volatile UInt32 ringCount;
    volatile UInt32 queued;
};
static TvqmV36FirstObservation gTvqmV36FirstPermit = {};
static TvqmV36FirstObservation gTvqmV36FirstCollision = {};
static inline void tvqmV36CaptureFirst(TvqmV36FirstObservation *row,
    UInt32 qid, UInt32 tid, UInt32 generation, UInt32 occupiedBits,
    UInt32 ringCount, UInt32 queued) {
    UInt32 expected = 0;
    if (!__atomic_compare_exchange_n(&row->state, &expected, 1U,
                                     false, __ATOMIC_ACQ_REL, __ATOMIC_ACQUIRE))
        return;
    __atomic_store_n(&row->qid, qid, __ATOMIC_RELAXED);
    __atomic_store_n(&row->tid, tid, __ATOMIC_RELAXED);
    __atomic_store_n(&row->generation, generation, __ATOMIC_RELAXED);
    __atomic_store_n(&row->occupiedBits, occupiedBits, __ATOMIC_RELAXED);
    __atomic_store_n(&row->ringCount, ringCount, __ATOMIC_RELAXED);
    __atomic_store_n(&row->queued, queued, __ATOMIC_RELAXED);
    __atomic_store_n(&row->state, 2U, __ATOMIC_RELEASE);
}
