static void mac1LinkV1Invalidate(void)
{
    /* No need to acquire the peer writer: epoch mismatch invalidates it. */
    __atomic_fetch_add(&gMac1LinkV1InvalidateEpoch, 1U, __ATOMIC_SEQ_CST);
    __atomic_store_n(&gMac1LinkV1LastTXMatch, 0U, __ATOMIC_RELAXED);
}

static void mac1LinkV1Observe(const uint8_t *src, UInt32 generation, UInt32 channel)
{
    if (!src || (src[0] & 1U) || channel == 0U) return;
    const UInt32 epoch = __atomic_load_n(&gMac1LinkV1InvalidateEpoch, __ATOMIC_SEQ_CST);
    UInt32 seq = __atomic_load_n(&gMac1LinkV1PeerSeq, __ATOMIC_SEQ_CST);
    if ((seq & 1U) || !__atomic_compare_exchange_n(&gMac1LinkV1PeerSeq,
            &seq, seq + 1U, false, __ATOMIC_SEQ_CST, __ATOMIC_SEQ_CST)) return;
    const bool sameCohort = gMac1LinkV1PeerValid &&
        gMac1LinkV1PeerGeneration == generation &&
        gMac1LinkV1PeerEpoch == epoch;
    const bool changed = sameCohort &&
        (gMac1LinkV1PeerChannel != channel || memcmp(gMac1LinkV1Peer, src, 6) != 0);
    if (changed) {
        __atomic_store_n(&gMac1LinkV1PeerAmbiguous, 1U, __ATOMIC_SEQ_CST);
        __atomic_fetch_add(&gMac1LinkV1Conflicts, 1U, __ATOMIC_RELAXED);
    }
    if (!sameCohort)
        __atomic_store_n(&gMac1LinkV1PeerAmbiguous, 0U, __ATOMIC_SEQ_CST);
    if (!sameCohort || !changed) {
        for (unsigned j = 0; j < 6; ++j)
            __atomic_store_n(&gMac1LinkV1Peer[j], src[j], __ATOMIC_SEQ_CST);
        __atomic_store_n(&gMac1LinkV1PeerChannel, channel, __ATOMIC_SEQ_CST);
    }
    __atomic_store_n(&gMac1LinkV1PeerGeneration, generation, __ATOMIC_SEQ_CST);
    __atomic_store_n(&gMac1LinkV1PeerEpoch, epoch, __ATOMIC_SEQ_CST);
    __atomic_store_n(&gMac1LinkV1PeerValid, 1U, __ATOMIC_SEQ_CST);
    if (!sameCohort) gMac1LinkV41RXConsistent = 1U;
    else if (!changed && gMac1LinkV41RXConsistent != 0xffffffffU)
        ++gMac1LinkV41RXConsistent;
    if (!changed || !sameCohort) {
        struct timeval rxnow = {};
        getmicrouptime(&rxnow);
        gMac1LinkV41RXSeconds = (UInt32)rxnow.tv_sec;
    }
    __atomic_store_n(&gMac1LinkV1PeerSeq, seq + 2U, __ATOMIC_SEQ_CST);
    __atomic_fetch_add(&gMac1LinkV1Observed, 1U, __ATOMIC_RELAXED);
}

static bool mac1LinkV1Match(const uint8_t *dst, UInt32 generation, UInt32 channel)
{
    const UInt32 epochBefore = __atomic_load_n(&gMac1LinkV1InvalidateEpoch, __ATOMIC_SEQ_CST);
    const UInt32 seqBefore = __atomic_load_n(&gMac1LinkV1PeerSeq, __ATOMIC_SEQ_CST);
    if (!dst || (dst[0] & 1U) || !channel || (seqBefore & 1U)) return false;
    uint8_t peer[6];
    for (unsigned j = 0; j < 6; ++j)
        peer[j] = __atomic_load_n(&gMac1LinkV1Peer[j], __ATOMIC_SEQ_CST);
    const UInt32 peerGeneration = __atomic_load_n(&gMac1LinkV1PeerGeneration, __ATOMIC_SEQ_CST);
    const UInt32 peerEpoch = __atomic_load_n(&gMac1LinkV1PeerEpoch, __ATOMIC_SEQ_CST);
    const UInt32 peerChannel = __atomic_load_n(&gMac1LinkV1PeerChannel, __ATOMIC_SEQ_CST);
    const UInt32 valid = __atomic_load_n(&gMac1LinkV1PeerValid, __ATOMIC_SEQ_CST);
    const UInt32 ambiguous = __atomic_load_n(&gMac1LinkV1PeerAmbiguous, __ATOMIC_SEQ_CST);
    return valid && !ambiguous && peerGeneration == generation &&
        peerEpoch == epochBefore && peerChannel == channel &&
        memcmp(peer, dst, 6) == 0 &&
        seqBefore == __atomic_load_n(&gMac1LinkV1PeerSeq, __ATOMIC_SEQ_CST) &&
        epochBefore == __atomic_load_n(&gMac1LinkV1InvalidateEpoch, __ATOMIC_SEQ_CST);
}
/* Only called when Apple's findCached(peerMgr, source-address) returned a peer.
 * Never retains the Apple pointer or asserts that the peer is authenticated. */
extern "C" void Mac1LinkV41AppleCacheObserve(const uint8_t *sa)
{
    if (!sa || (sa[0] & 1U)) return;
    UInt32 seq = __atomic_load_n(&gMac1LinkV41CacheSeq, __ATOMIC_SEQ_CST);
    if ((seq & 1U) || !__atomic_compare_exchange_n(&gMac1LinkV41CacheSeq,
            &seq, seq + 1U, false, __ATOMIC_SEQ_CST, __ATOMIC_SEQ_CST)) return;
    for (unsigned j=0; j<6; ++j)
        __atomic_store_n(&gMac1LinkV41CachePeer[j], sa[j], __ATOMIC_SEQ_CST);
    struct timeval now = {};
    getmicrouptime(&now);
    __atomic_store_n(&gMac1LinkV41CacheSeconds, (UInt32)now.tv_sec, __ATOMIC_SEQ_CST);
    __atomic_store_n(&gMac1LinkV41CacheSeq, seq+2U, __ATOMIC_SEQ_CST);
    __atomic_fetch_add(&gMac1LinkV41CacheObserved, 1U, __ATOMIC_RELAXED);
}
#endif

