static bool
airplayRxSyncOn(void)
{
    if (gAirplayRxSyncOn < 0) {
        int v = 0;
        gAirplayRxSyncOn = PE_parse_boot_argn("-awdlrxsyncoff", &v, sizeof(v)) ? 0 : 1;
    }
    return gAirplayRxSyncOn == 1;
}
