// 2F diagnostics: first synchronous attach only; atomics touch ordinary RAM only.
// No new hardware reads, DMA operations, explicit locks/waits, or callback ownership.
// 2G: bounded, immutable-after-commit RX observations. Never select a different
// packet, alter DMA, or use a diagnostic header/address to control the driver.
uint64_t ItlIwx::time2GNow()
{
    uint64_t diagAbsolute2G, diagNanoseconds2G;
    clock_get_uptime(&diagAbsolute2G);
    absolutetime_to_nanoseconds(diagAbsolute2G, &diagNanoseconds2G);
    return diagNanoseconds2G;
}
void ItlIwx::time2GMark(unsigned index)
{
    if (alive2FOwned()) fTime2G[index] = time2GNow();
}
void ItlIwx::rx2GWord(int slot, unsigned word, uint32_t value)
{
    if (slot >= 0)
        __atomic_store_n(&fRx2GLive.record[slot].word[word], value, __ATOMIC_RELAXED);
}
void ItlIwx::rx2GFinish(int slot, uint32_t outcome)
{
    if (slot < 0 || __atomic_load_n(&fRx2GLive.record[slot].word[0], __ATOMIC_ACQUIRE)) return;
    rx2GWord(slot, 11, outcome);
    __atomic_store_n(&fRx2GLive.record[slot].word[0], 1U, __ATOMIC_RELEASE);
}
int ItlIwx::rx2GBegin(struct iwx_softc *sc, struct iwx_rx_data *data, mbuf_t m)
{
    if (!__atomic_load_n(&fAlive2FPhase, __ATOMIC_RELAXED) ||
        sc->sc_device_family < IWX_DEVICE_FAMILY_AX210) return -1;
    const unsigned slot = __atomic_fetch_add(&fRx2GTotal, 1U, __ATOMIC_RELAXED);
    if (slot >= 16) return -1;
    rx2GWord(slot, 1, __atomic_load_n(&fAlive2FEvents[4], __ATOMIC_RELAXED));
    rx2GWord(slot, 2, sc->rxq.cur);
    rx2GWord(slot, 3, __atomic_load_n(&fRx2GHw, __ATOMIC_RELAXED));
    rx2GWord(slot, 4, m != nullptr);
    if (m) rx2GWord(slot, 13, static_cast<uint32_t>(mbuf_len(m)));
    if (data->map && m) {
        rx2GWord(slot, 12, data->map->dm_nsegs);
        if (data->map->dm_nsegs > 0) {
        rx2GWord(slot, 5, static_cast<uint32_t>(data->map->dm_segs[0].length));
        __atomic_store_n(&fRx2GLive.record[slot].address[0], uint64_t(data->map->dm_segs[0].location), __ATOMIC_RELAXED);
        }
    }
    const unsigned cur = sc->rxq.cur;
    if (cur < IWX_RX_MQ_RING_COUNT && sc->rxq.used_desc_dma.vaddr && sc->rxq.desc) {
        // Normal RAM in existing prepared rings, not MMIO. Completion bytes are
        // evidence only; CPU/DMA visibility and device finality are not assumed.
        const uint8_t *completion = static_cast<const uint8_t *>(sc->rxq.used_desc_dma.vaddr) + cur * sizeof(iwx_rx_completion_desc);
        for (unsigned i = 0; i < 8; ++i) {
            uint32_t value; memcpy(&value, completion + 4*i, sizeof(value));
            rx2GWord(slot, 14+i, value);
        }
        const uint8_t *freeDesc = static_cast<const uint8_t *>(sc->rxq.desc) + cur * 16 /* asserted below */;
        uint32_t tag; uint64_t address;
        memcpy(&tag, freeDesc, sizeof(tag)); memcpy(&address, freeDesc + 8, sizeof(address));
        rx2GWord(slot, 22, tag);
        __atomic_store_n(&fRx2GLive.record[slot].address[1], address, __ATOMIC_RELAXED);
        // Independently bounded alternate-tag header observation. No new mapping,
        // retained mbuf, delivery, or change to the stock data[cur] selection.
        const uint16_t tagIndex = __atomic_load_n(&fRx2GLive.record[slot].word[15], __ATOMIC_RELAXED) & 0xffff;
        rx2GWord(slot, 28, tagIndex);
        if (tagIndex < IWX_RX_MQ_RING_COUNT) {
            mbuf_t other = sc->rxq.data[tagIndex].m;
            if (other && mbuf_len(other) >= 8 && mbuf_data(other)) {
                rx2GWord(slot, 29, static_cast<uint32_t>(mbuf_len(other)));
                uint32_t a, b; memcpy(&a, mbuf_data(other), 4); memcpy(&b, static_cast<const uint8_t *>(mbuf_data(other))+4, 4);
                rx2GWord(slot, 30, a); rx2GWord(slot, 31, b);
            }
        }
    }
    if (!m) rx2GFinish(slot, 1);
    return slot;
}
void ItlIwx::rx2GHeader(int slot, struct iwx_rx_packet *pkt, uint32_t code, int valid)
{
    if (slot < 0) return;
    uint32_t header; memcpy(&header, &pkt->hdr, sizeof(header));
    rx2GWord(slot, 6, pkt->len_n_flags); rx2GWord(slot, 7, header);
    rx2GWord(slot, 8, valid); rx2GWord(slot, 10, code);
}
void ItlIwx::rx2GSnapshot()
{
    fRx2GWire.header[0] = 1;
    fRx2GWire.header[1] = __atomic_load_n(&fRx2GTotal, __ATOMIC_RELAXED);
    fRx2GWire.header[2] = 0;
    fRx2GWire.header[3] = 16;
    for (unsigned i = 0; i < 16; ++i) {
        if (!__atomic_load_n(&fRx2GLive.record[i].word[0], __ATOMIC_ACQUIRE)) continue;
        for (unsigned j = 0; j < 32; ++j)
            fRx2GWire.record[i].word[j] = __atomic_load_n(&fRx2GLive.record[i].word[j], __ATOMIC_RELAXED);
        for (unsigned j = 0; j < 2; ++j)
            fRx2GWire.record[i].address[j] = __atomic_load_n(&fRx2GLive.record[i].address[j], __ATOMIC_RELAXED);
        ++fRx2GWire.header[2];
    }
}


// 2H functional RX experiment: mapped DMA backing belongs to the hardware slot,
// independently of the mbuf copied/delivered to the network stack. Allocate only
// during synchronous ring construction; no prepare/remap in RX callbacks.
void ItlIwx::rx2HError(unsigned slot, unsigned stage, IOReturn result)
{
    uint32_t expected = 0;
    if (__atomic_compare_exchange_n(&fRxMap2H[3], &expected, 1U, false,
                                     __ATOMIC_ACQ_REL, __ATOMIC_RELAXED)) {
        __atomic_store_n(&fRxMap2H[4], slot, __ATOMIC_RELAXED);
        __atomic_store_n(&fRxMap2H[5], stage, __ATOMIC_RELAXED);
        __atomic_store_n(&fRxMap2H[6], uint32_t(result), __ATOMIC_RELAXED);
        __atomic_store_n(&fRxMap2H[3], 2U, __ATOMIC_RELEASE);
    }
}

// Reusable backing primitive; RX/TX/command publication and retirement policies
// remain separate. This helper has no ring, mbuf, callback or provider ownership.
static IOReturn allocatePacketBacking2H(struct iwx_dma_info *dma, size_t size,
                                        unsigned alignment, unsigned *stage)
{
    *stage = 1;
    IOBufferMemoryDescriptor *bmd = IOBufferMemoryDescriptor::inTaskWithPhysicalMask(
        kernel_task, kIODirectionInOut | kIOMemoryPhysicallyContiguous | kIOMapInhibitCache,
        size, DMA_BIT_MASK(64));
    if (!bmd) return kIOReturnNoMemory;
    *stage = 2;
    IOReturn result = bmd->prepare();
    if (result != kIOReturnSuccess) { bmd->release(); return result; }
    *stage = 3;
    IODMACommand *cmd = IODMACommand::withSpecification(kIODMACommandOutputHost64,
        64, 0, IODMACommand::kMapped, 0, alignment);
    if (!cmd) { bmd->complete(); bmd->release(); return kIOReturnNoMemory; }
    *stage = 4;
    result = cmd->setMemoryDescriptor(bmd);
    if (result != kIOReturnSuccess) {
        cmd->clearMemoryDescriptor(); cmd->release(); bmd->complete(); bmd->release(); return result;
    }
    *stage = 5;
    UInt64 offset = 0;
    UInt32 count = 1;
    IODMACommand::Segment64 seg = {};
    result = cmd->gen64IOVMSegments(&offset, &seg, &count);
    if (result == kIOReturnSuccess && (count != 1 || offset != size || seg.fLength != size ||
        !alignment || (seg.fIOVMAddr & (alignment - 1)) || !bmd->getBytesNoCopy())) {
        *stage = 6;
        result = kIOReturnBadArgument;
    }
    if (result != kIOReturnSuccess) {
        cmd->clearMemoryDescriptor(); cmd->release(); bmd->complete(); bmd->release(); return result;
    }
    void *bytes = bmd->getBytesNoCopy();
    memset(bytes, 0, size);
    *stage = 7;
    result = cmd->synchronize(kIODirectionOut);
    if (result != kIOReturnSuccess) {
        cmd->clearMemoryDescriptor(); cmd->release(); bmd->complete(); bmd->release(); return result;
    }
    dma->paddr = seg.fIOVMAddr;
    dma->vaddr = bytes;
    dma->size = size;
    dma->buffer = bmd;
    dma->cmd = cmd;
    *stage = 0;
    return kIOReturnSuccess;
}


// PC1: reset recovery uses the hardware stop/reset boundary AND the same
// workloop gate as ordinary TX and RX notifications. Quarantined payloads are
// never recycled; this is not a software-generation-only completion terminal.
void ItlIwx::pc1Report()
{
    if (fPc1Snapshots >= 32 || !pci.pa_tag) return;
    uint32_t v[20] = {1, ++fPc1Snapshots, fPc1ResetEpoch, fPc1TerminalEpoch,
        fPc1ExpectedGeneration, unsigned(com.sc_generation), fPc1LastMaster,
        __atomic_load_n(&fPc1Fault,__ATOMIC_ACQUIRE), fPc1Recoveries, fPc1QuarantineCount,
        __atomic_load_n(&fPc1Suspended,__ATOMIC_ACQUIRE),
        __atomic_load_n(&fTx2IBlocked,__ATOMIC_ACQUIRE),
        __atomic_load_n(&fTx2JAdmission,__ATOMIC_ACQUIRE),
        fPc1DroppedCompletion, fPc1StaleFlush, fPc1LastRefusal, fPc1PublishFailures};
    for (unsigned i=0;i<kTx2ICount;++i) {
        const unsigned s=__atomic_load_n(&fTx2I[i].state,__ATOMIC_ACQUIRE);
        if (s==Tx2IQuarantined) ++v[17];
        if (s==Tx2IInflight || s==Tx2ICopying) ++v[18];
    }
    v[19]=32;
    if (!pci.pa_tag->setProperty("KGP_PC1",v,sizeof(v))) ++fPc1PublishFailures;
    XYLog("KGP_PC1 reset=%u terminal=%u generation=%u master=%u recoveries=%u retained=%u blocked=%u fault=%u refusal=%u\n",
          v[2],v[3],v[5],v[6],v[8],v[17],v[11],v[7],v[15]);
}
IOReturn ItlIwx::pc1StopAction(OSObject *owner,void *sc,void *origin,void *,void *)
{
    auto that=static_cast<ItlIwx *>(owner);
    that->iwx_stop_device(static_cast<iwx_softc *>(sc),unsigned(uintptr_t(origin)));
    return kIOReturnSuccess;
}
IOReturn ItlIwx::pc1RingAction(OSObject *owner,void *sc,void *ring,void *,void *)
{
    auto that=static_cast<ItlIwx *>(owner);
    that->iwx_reset_tx_ring(static_cast<iwx_softc *>(sc),static_cast<iwx_tx_ring *>(ring));
    return kIOReturnSuccess;
}
IOReturn ItlIwx::pc1AdvanceAction(OSObject *owner,void *arg,void *,void *,void *)
{
    auto that=static_cast<ItlIwx *>(owner);
    auto c=static_cast<Pc1Advance *>(arg);
    if (c->generation!=unsigned(that->com.sc_generation) ||
        __atomic_load_n(&that->fPc1Suspended,__ATOMIC_ACQUIRE)) {
        ++that->fPc1StaleFlush;return kIOReturnAborted;
    }
    /*
     * FLUSHRETIRE: this runs only for a TXPATH_FLUSH firmware response, which
     * reports read_after_flush: the firmware has released every TFD before it
     * (Linux iwlwifi reclaims/frees them here). Retire as a normal firmware
     * completion. 'false' quarantined them and blocked all TX until the next
     * full re-init, which dropped the next auth frame on every network switch.
     */
    {
        int before = c->ring->queued;
        that->iwx_ampdu_txq_advance(&that->com,c->ring,c->index,true);
        int retired = before - c->ring->queued;
        if (retired > 0) {
            ieee80211_js.flushRetired += (u_int32_t)retired;
            IEEE80211_JOINSTAT(flushCalls);
        }
    }
    return kIOReturnSuccess;
}
IOReturn ItlIwx::pc1StopEndAction(OSObject *owner,void *,void *,void *,void *)
{
    auto that=static_cast<ItlIwx *>(owner);
    // A full stop adds one software generation after the device stop.
    if (that->fPc1TerminalEpoch==that->fPc1ResetEpoch && that->fPc1TerminalEpoch &&
        unsigned(that->com.sc_generation)==that->fPc1ExpectedGeneration)
        ++that->fPc1ExpectedGeneration;
    that->pc1Report();return kIOReturnSuccess;
}
#ifdef DEBUG
/* V31: forward declarations only; the recovery proof is published by the
 * existing AX210 stop path after a positive master-stop and processor reset. */
static uint64_t mac1S3FenceStopSerial(void);
static void mac1S3FenceResetVerified(struct iwx_softc *, uint64_t, uint32_t);
static void mac1S3FenceRecoveryPassed(struct iwx_softc *, uint32_t);
/* V83: read-only registry rejection diagnosis. Must be invoked only in the
 * existing PC1 main-workloop gate. Never calls beginVerifiedEpoch(). */
static UInt32 v83RegistryEpochRejectMask(uint32_t nextGeneration,
    bool positiveReset, bool commandsQuiescent, bool callbacksQuiescent);

static UInt32 v81S7BusyMask(void);
#endif

#ifdef DEBUG
/* V79: count every AX210 host iwx_send_cmd() invocation until its return,
 * even when a positive reset invalidates its Cmd2K serial. Observation only:
 * a zero count does NOT establish independent RX/firmware callback quiescence.
 * Never use these counters to approve a registry epoch, TX, DMA, or reclaim. */
static volatile UInt32 gV79CmdSendLive = 0;
static volatile UInt32 gV79CmdSendStarts = 0;
static volatile UInt32 gV79CmdSendEnds = 0;
static volatile UInt32 gV79PositiveResetSerial = 0;
static volatile UInt32 gV79CmdCrossResetExits = 0;
__attribute__((unused)) static volatile UInt32 gV79CmdLiveAtReset = 0;
__attribute__((unused)) static volatile UInt32 gV79CmdLiveAtRecovery = 0;

/* V80 host-only reset witness. The snapshot is NON-authoritative: the recovery
 * callback runs after stock admission may have reopened, and RX callback/DMA
 * retirement is not established here. Never use this to approve station-3 TX. */
static volatile UInt32 gV80WitnessSerial = 0;
static volatile UInt32 gV80WitnessEpoch = 0;
static volatile UInt32 gV80WitnessGeneration = 0;
static volatile UInt32 gV80StartsAtReset = 0;
static volatile UInt32 gV80EndsAtReset = 0;
static volatile UInt32 gV80CrossExitsAtReset = 0;
static volatile UInt32 gV80LiveAtWitness = 0;
static bool v80HostSnapshotMatches(
    UInt32 witnessSerial, UInt32 currentSerial,
    UInt32 witnessEpoch, UInt32 recoveryEpoch,
    UInt32 witnessGeneration, UInt32 recoveryGeneration,
    UInt32 liveAtReset, UInt32 liveAtRecovery,
    UInt32 startsAtReset, UInt32 endsAtReset,
    UInt32 startsAtRecovery, UInt32 endsAtRecovery,
    UInt32 crossesAtReset, UInt32 crossesAtRecovery) {
    return witnessSerial != 0U && witnessSerial == currentSerial &&
        witnessEpoch != 0U && witnessEpoch == recoveryEpoch &&
        witnessGeneration != 0U && witnessGeneration == recoveryGeneration &&
        liveAtReset == 0U && liveAtRecovery == 0U &&
        startsAtReset == endsAtReset &&
        startsAtRecovery == endsAtRecovery &&
        crossesAtReset == crossesAtRecovery;
}

/* V81: diagnostic HOST prerequisite mask. A zero value is NOT private
 * ownership, callback-quiescence, or DMA-retirement proof. This function
 * never calls beginVerifiedEpoch() or authorizes a queue. */
static UInt32 v81HostRejectMask(bool witnessMatched,
    bool positiveMasterReset, bool terminalEpochMatches,
    bool noActiveCmdCallers, UInt32 s7BusyMask) {
    UInt32 rejected = 0U;
    if (!witnessMatched) rejected |= (1U << 0);
    if (!positiveMasterReset) rejected |= (1U << 1);
    if (!terminalEpochMatches) rejected |= (1U << 2);
    if (!noActiveCmdCallers) rejected |= (1U << 3);
    return rejected | ((s7BusyMask & 31U) << 4);
}

/* V84: classify a snapshot taken BEFORE PC1 reopens ordinary TX.
 * This is observational. A zero mask is NOT proof of all callback retirement,
 * DMA safety, registry epoch permission, or firmware station ownership.
 * Bits: 0=TX admission not closed, 1=TX block not set, 2=live command caller,
 * 3=command starts/ends differ, 4=command reset active, 5=S7 guard busy,
 * 6=V80 reset witness mismatch, 7=positive master-reset proof absent. */
static UInt32 v84PreOpenRejectMask(bool admissionClosed, bool txBlocked,
    bool noLiveCmdCallers, bool cmdStartsMatchEnds, bool noCmdReset,
    bool noS7Busy, bool witnessMatched, bool positiveReset) {
    UInt32 m = 0U;
    if (!admissionClosed) m |= 1U << 0;
    if (!txBlocked) m |= 1U << 1;
    if (!noLiveCmdCallers) m |= 1U << 2;
    if (!cmdStartsMatchEnds) m |= 1U << 3;
    if (!noCmdReset) m |= 1U << 4;
    if (!noS7Busy) m |= 1U << 5;
    if (!witnessMatched) m |= 1U << 6;
    if (!positiveReset) m |= 1U << 7;
    return m;
}

/* V85: PC1 admission/block pair at the V84 pre-open snapshot.
 * This class explains V84 bits 0 and 1; it is NOT a safety verdict.
 * 0: admission zero / TX unblocked (PC1 accepts; possibly idle stop)
 * 1: admission closed / TX blocked (PC1 accepts; held stop)
 * 2: admission zero / TX blocked (PC1 accepts; mixed pair)
 * 3: admission closed / TX unblocked (PC1 accepts; mixed pair)
 * 4: admission neither zero nor closed (PC1 refuses)
 * All states remain unproven for callback/DMA/firmware ownership. */
static UInt32 v85PreOpenAdmissionClass(UInt32 admission, bool blocked,
    UInt32 closedValue) {
    if (admission == 0U) return blocked ? 2U : 0U;
    if (admission == closedValue) return blocked ? 1U : 3U;
    return 4U;
}

struct V79ScopedCmdSend {
    bool active;
    UInt32 resetSerial;
    explicit V79ScopedCmdSend(const struct iwx_softc *sc)
        : active(sc && sc->sc_device_family >= IWX_DEVICE_FAMILY_AX210),
          resetSerial(0U) {
        if (!active) return;
        __atomic_add_fetch(&gV79CmdSendLive, 1U, __ATOMIC_ACQ_REL);
        resetSerial = __atomic_load_n(&gV79PositiveResetSerial, __ATOMIC_ACQUIRE);
        __atomic_add_fetch(&gV79CmdSendStarts, 1U, __ATOMIC_RELAXED);
    }
    ~V79ScopedCmdSend() {
        if (!active) return;
        if (__atomic_load_n(&gV79PositiveResetSerial, __ATOMIC_ACQUIRE) != resetSerial)
            __atomic_add_fetch(&gV79CmdCrossResetExits, 1U, __ATOMIC_RELAXED);
        __atomic_add_fetch(&gV79CmdSendEnds, 1U, __ATOMIC_RELAXED);
        __atomic_sub_fetch(&gV79CmdSendLive, 1U, __ATOMIC_ACQ_REL);
    }
    V79ScopedCmdSend(const V79ScopedCmdSend&) = delete;
    V79ScopedCmdSend& operator=(const V79ScopedCmdSend&) = delete;
};
#endif

IOReturn ItlIwx::pc1RecoverAction(OSObject *owner,void *arg,void *,void *,void *)
{
    auto that=static_cast<ItlIwx *>(owner);const unsigned generation=unsigned(uintptr_t(arg));
    if (generation!=unsigned(that->com.sc_generation)) return kIOReturnAborted;
    if (!__atomic_load_n(&that->fPc1Suspended,__ATOMIC_ACQUIRE)) return kIOReturnSuccess;
    unsigned refusal=0,quarantines=0;
    if (__atomic_load_n(&that->fPc1Fault,__ATOMIC_ACQUIRE) || !that->fPc1TerminalEpoch || that->fPc1TerminalEpoch!=that->fPc1ResetEpoch) refusal=1;
    if (generation!=unsigned(that->com.sc_generation) || generation!=that->fPc1ExpectedGeneration) refusal=2;
    if (!that->com.sc_uc.uc_ok || __atomic_load_n(&that->fCmd2KFrozen,__ATOMIC_SEQ_CST)) refusal=3;
    if (__atomic_load_n(&that->fTx2IStats[16],__ATOMIC_ACQUIRE)) refusal=4;
    for (unsigned i=0;i<kTx2ICount;++i) {
        const unsigned s=__atomic_load_n(&that->fTx2I[i].state,__ATOMIC_ACQUIRE);
        if (s==Tx2IQuarantined) ++quarantines;
        else if(s!=Tx2IFree) refusal=5;
    }
    if (quarantines!=that->fPc1QuarantineCount) refusal=6;
    uint32_t admission=__atomic_load_n(&that->fTx2JAdmission,__ATOMIC_ACQUIRE);
    if (admission!=0 && admission!=kTx2JClosed) refusal=7;
#ifdef DEBUG
    /* V84: read the existing guards BEFORE the recovery gate lowers the
     * normal TX block and reopens ordinary admission. No state mutation. */
    const UInt32 v84PreAdmissionClosed = (admission == kTx2JClosed) ? 1U : 0U;
    const UInt32 v84PreTxBlocked = __atomic_load_n(&that->fTx2IBlocked,
        __ATOMIC_ACQUIRE) != 0U ? 1U : 0U;
    const UInt32 v84PreCmdLive = __atomic_load_n(&gV79CmdSendLive,
        __ATOMIC_ACQUIRE);
    const UInt32 v84PreCmdStarts = __atomic_load_n(&gV79CmdSendStarts,
        __ATOMIC_ACQUIRE);
    const UInt32 v84PreCmdEnds = __atomic_load_n(&gV79CmdSendEnds,
        __ATOMIC_ACQUIRE);
    const UInt32 v84PreCmdResetDepth = __atomic_load_n(&that->fCmd2KResetDepth,
        __ATOMIC_SEQ_CST);
    const UInt32 v84PreS7Busy = v81S7BusyMask();
    /* V85: preserve the actual pre-CAS admission sample. Neither a
     * zero/zero pair nor closed/blocked proves all callbacks retired. */
    const UInt32 v85PreAdmissionRaw = admission;
    const UInt32 v85PreSuspended = __atomic_load_n(&that->fPc1Suspended,
        __ATOMIC_ACQUIRE) != 0U ? 1U : 0U;
#endif
    if (!refusal) {
        // Admission stays closed while blocked is lowered. A concurrent stop
        // changes stop depth; the CAS then fails and blocked is restored.
        __atomic_store_n(&that->fTx2IBlocked,0U,__ATOMIC_RELEASE);
        if (!__atomic_compare_exchange_n(&that->fTx2JAdmission,&admission,0U,false,
                                         __ATOMIC_ACQ_REL,__ATOMIC_ACQUIRE)) refusal=8;
    }
    if (refusal) {
        __atomic_store_n(&that->fTx2IBlocked,1U,__ATOMIC_RELEASE);
        that->fPc1LastRefusal=refusal;that->pc1Report();return kIOReturnNotReady;
    }
    __atomic_store_n(&that->fPc1Suspended,0U,__ATOMIC_RELEASE);
    
    ++that->fPc1Recoveries;
    that->fPc1LastRefusal=0;
#ifdef DEBUG
    /* Exactly here: PC1's full generation, master-stop, firmware-ready,
     * command-reset and TX-quiescence checks have all passed under its gate.
     * The early !fPc1Suspended success return deliberately does NOT reopen. */
    mac1S3FenceRecoveryPassed(&that->com, that->fPc1ResetEpoch);
    /* V79: report observational host-call lifetime only. PC1 recovery is NOT
     * callback-quiescence proof and never authorizes beginVerifiedEpoch(). */
    const UInt32 v79LiveNow = __atomic_load_n(&gV79CmdSendLive, __ATOMIC_ACQUIRE);
    __atomic_store_n(&gV79CmdLiveAtRecovery, v79LiveNow, __ATOMIC_RELEASE);
    if (auto *v79Publisher = that->getController()) {
        v79Publisher->setProperty("AIRPLAYV79CmdLiveAtReset",
            (uint64_t)__atomic_load_n(&gV79CmdLiveAtReset, __ATOMIC_ACQUIRE), 32);
        v79Publisher->setProperty("AIRPLAYV79CmdLiveAtRecovery", (uint64_t)v79LiveNow, 32);
        v79Publisher->setProperty("AIRPLAYV79CmdCrossResetExits",
            (uint64_t)__atomic_load_n(&gV79CmdCrossResetExits, __ATOMIC_ACQUIRE), 32);
        v79Publisher->setProperty("AIRPLAYV79CmdSendStarts",
            (uint64_t)__atomic_load_n(&gV79CmdSendStarts, __ATOMIC_ACQUIRE), 32);
        v79Publisher->setProperty("AIRPLAYV79CmdSendEnds",
            (uint64_t)__atomic_load_n(&gV79CmdSendEnds, __ATOMIC_ACQUIRE), 32);
        v79Publisher->setProperty("AIRPLAYV79RegistryEpochApproved", (uint64_t)0U, 32);
        /* V80: true means the sampled HOST caller counts agree, NOT that
         * all firmware callbacks/DMA or private ownership are retired. */
        const UInt32 v80Serial = __atomic_load_n(&gV80WitnessSerial, __ATOMIC_ACQUIRE);
        const UInt32 v80ResetLive = __atomic_load_n(&gV80LiveAtWitness, __ATOMIC_ACQUIRE);
        const bool v80Matched = v80HostSnapshotMatches(
            v80Serial,
            __atomic_load_n(&gV79PositiveResetSerial, __ATOMIC_ACQUIRE),
            __atomic_load_n(&gV80WitnessEpoch, __ATOMIC_ACQUIRE),
            (UInt32)that->fPc1ResetEpoch,
            __atomic_load_n(&gV80WitnessGeneration, __ATOMIC_ACQUIRE),
            (UInt32)that->com.sc_generation,
            v80ResetLive, v79LiveNow,
            __atomic_load_n(&gV80StartsAtReset, __ATOMIC_ACQUIRE),
            __atomic_load_n(&gV80EndsAtReset, __ATOMIC_ACQUIRE),
            __atomic_load_n(&gV79CmdSendStarts, __ATOMIC_ACQUIRE),
            __atomic_load_n(&gV79CmdSendEnds, __ATOMIC_ACQUIRE),
            __atomic_load_n(&gV80CrossExitsAtReset, __ATOMIC_ACQUIRE),
            __atomic_load_n(&gV79CmdCrossResetExits, __ATOMIC_ACQUIRE));
        v79Publisher->setProperty("AIRPLAYV80WitnessEpoch",
            (uint64_t)__atomic_load_n(&gV80WitnessEpoch, __ATOMIC_ACQUIRE), 32);
        v79Publisher->setProperty("AIRPLAYV80WitnessGeneration",
            (uint64_t)__atomic_load_n(&gV80WitnessGeneration, __ATOMIC_ACQUIRE), 32);
        v79Publisher->setProperty("AIRPLAYV80HostSnapshotMatched",
            (uint64_t)(v80Matched ? 1U : 0U), 32);
        v79Publisher->setProperty("AIRPLAYV80RegistryEpochApproved", (uint64_t)0U, 32);
        /* V81: this mask covers selected HOST prerequisites only. A zero
         * mask is not proof that the registry itself can advance. */
        const UInt32 v81Reject = v81HostRejectMask(
            v80Matched,
            that->fPc1LastMaster != 0,
            that->fPc1TerminalEpoch != 0U &&
                that->fPc1TerminalEpoch == that->fPc1ResetEpoch,
            v79LiveNow == 0U,
            v81S7BusyMask());
        v79Publisher->setProperty("AIRPLAYV81HostRejectMask", (uint64_t)v81Reject, 32);
        v79Publisher->setProperty("AIRPLAYV81HostPrereqsObserved",
            (uint64_t)(v81Reject == 0U ? 1U : 0U), 32);
        v79Publisher->setProperty("AIRPLAYV81RegistryEpochApproved", (uint64_t)0U, 32);
        /* V83: combine two distinct, OBSERVATIONAL rejection layers.
         * Host: bits 0..8 from V81. Registry: bits 9..19 from V82.
         * NEVER translate a zero into epoch, TX, or DMA authorization.
         * V79 observes callers only; full firmware-command and callback
         * quiescence are unproven and supplied as FALSE on purpose. */
        const bool v83PositiveReset = that->fPc1LastMaster != 0 &&
            that->fPc1TerminalEpoch != 0U &&
            that->fPc1TerminalEpoch == that->fPc1ResetEpoch;
        const UInt32 v83RegistryReject = v83RegistryEpochRejectMask(
            (uint32_t)that->com.sc_generation,
            v83PositiveReset, false, false);
        v79Publisher->setProperty("AIRPLAYV83HostRejectMask",
            (uint64_t)v81Reject, 32);
        v79Publisher->setProperty("AIRPLAYV83RegistryRejectMask",
            (uint64_t)v83RegistryReject, 32);
        v79Publisher->setProperty("AIRPLAYV83CombinedRejectMask",
            (uint64_t)(v81Reject | (v83RegistryReject << 9)), 32);
        v79Publisher->setProperty("AIRPLAYV83RegistryEpochApproved", (uint64_t)0U, 32);
        /* V84: compare a PRE-open snapshot to V80/V83's observations.
         * Post-open counters are NOT a substitute for the pre-open sample;
         * neither snapshot authorizes private TX or a registry transition. */
        const UInt32 v84Reject = v84PreOpenRejectMask(
            v84PreAdmissionClosed != 0U, v84PreTxBlocked != 0U,
            v84PreCmdLive == 0U, v84PreCmdStarts == v84PreCmdEnds,
            v84PreCmdResetDepth == 0U, v84PreS7Busy == 0U,
            v80Matched, v83PositiveReset);
        v79Publisher->setProperty("AIRPLAYV84PreOpenRejectMask", (uint64_t)v84Reject, 32);
        v79Publisher->setProperty("AIRPLAYV84PreOpenCmdLive", (uint64_t)v84PreCmdLive, 32);
        v79Publisher->setProperty("AIRPLAYV84PreOpenS7Busy", (uint64_t)v84PreS7Busy, 32);
        v79Publisher->setProperty("AIRPLAYV84PreOpenResetDepth", (uint64_t)v84PreCmdResetDepth, 32);
        v79Publisher->setProperty("AIRPLAYV84PreOpenStarts", (uint64_t)v84PreCmdStarts, 32);
        v79Publisher->setProperty("AIRPLAYV84PreOpenEnds", (uint64_t)v84PreCmdEnds, 32);
        v79Publisher->setProperty("AIRPLAYV84RegistryEpochApproved", (uint64_t)0U, 32);
        /* V85: do not reinterpret V84's original strict mask as firmware
         * authorization. Classify the accepted pair separately. */
        const UInt32 v85AdmissionClass = v85PreOpenAdmissionClass(
            v85PreAdmissionRaw, v84PreTxBlocked != 0U, kTx2JClosed);
        v79Publisher->setProperty("AIRPLAYV85PreOpenAdmissionRaw", (uint64_t)v85PreAdmissionRaw, 32);
        v79Publisher->setProperty("AIRPLAYV85PreOpenBlockedRaw", (uint64_t)v84PreTxBlocked, 32);
        v79Publisher->setProperty("AIRPLAYV85PreOpenSuspended", (uint64_t)v85PreSuspended, 32);
        v79Publisher->setProperty("AIRPLAYV85PreOpenAdmissionClass", (uint64_t)v85AdmissionClass, 32);
        v79Publisher->setProperty("AIRPLAYV85RegistryEpochApproved", (uint64_t)0U, 32);
    }
#endif
#ifdef DEBUG
    /* Observation only. No station-3 retirement authorization. */
    if (that->pci.pa_tag) {
        const uint32_t record[] = {
            1U,
            that->fPc1ResetEpoch,
            that->fPc1TerminalEpoch,
            that->fPc1ExpectedGeneration,
            generation,
            (uint32_t)that->fPc1LastMaster,
            __atomic_load_n(&that->fPc1Fault, __ATOMIC_ACQUIRE),
            __atomic_load_n(&that->fCmd2KFrozen, __ATOMIC_SEQ_CST),
            __atomic_load_n(&that->fTx2IStats[16], __ATOMIC_ACQUIRE),
            that->fPc1Recoveries
        };
        OSData *data = OSData::withBytes(record, sizeof(record));
        if (data) {
            that->pci.pa_tag->setProperty(
                "AIRPLAYDIAGS3PC1RecoveredV1", data);
            data->release();
        }
    }
#endif
    that->pc1Report();
    return kIOReturnSuccess;

}

// 2I ordinary-TX experiment. No mapping/prepare/allocation in packet callbacks.
// Free -> Copying -> Inflight -> Free requires a normal firmware TX/BA retirement.
// All other retirement quarantines backing and disables ordinary TX for this HAL.
// Quarantine deliberately remains prepared even when the HAL is freed: an errno,
// software ring reset, flush response or lost mbuf is not used as a DMA fence.
static_assert(sizeof(iwx_tx_data) == 40, "2I must not grow the stock x86_64 TX slot");
static_assert(offsetof(iwx_tx_data, type) == 36, "stock TX slot prefix changed");
static_assert(offsetof(iwx_tx_data, tx2I_token) == 38, "use only stock tail padding");

void ItlIwx::tx2IReport(unsigned reason)
{
    // Bounded snapshots only: allocation, first error/quarantine, and selected
    // publication/completion milestones. No provider ownership is added.
    uint32_t wire[32] = {};
    const uint32_t first = __atomic_load_n(&fTx2IStats[16], __ATOMIC_ACQUIRE);
    for (unsigned i = 0; i < 32; ++i)
        wire[i] = __atomic_load_n(&fTx2IStats[i], __ATOMIC_RELAXED);
    wire[0] = 1; wire[1] = reason;
    wire[14] = __atomic_load_n(&fTx2IBlocked, __ATOMIC_ACQUIRE);
    wire[16] = first;
    if (first != 2) wire[17] = wire[18] = wire[19] = 0;
    const bool ok = pci.pa_tag && pci.pa_tag->setProperty("KGP_TX_2I", wire, sizeof(wire));
    if (!ok) __atomic_fetch_add(&fTx2IStats[15], 1U, __ATOMIC_RELAXED);
    uint64_t sample[4] = {};
    if (__atomic_load_n(&fTx2IStats[20], __ATOMIC_ACQUIRE) == 2) {
        for (unsigned i = 0; i < 4; ++i)
            sample[i] = __atomic_load_n(&fTx2IFirst[i], __ATOMIC_RELAXED);
        if (pci.pa_tag) pci.pa_tag->setProperty("KGP_TX_FIRST_2I", sample, sizeof(sample));
    }
    XYLog("KGP_TX_2I reason=%u allocated=%u submitted=%u completed=%u quarantined=%u blocked=%u first=%u:%u:0x%08x property=%u\n",
          reason, wire[2], wire[5], wire[6], wire[7], wire[14],
          wire[17], wire[18], wire[19], unsigned(ok));
}
void ItlIwx::tx2IError(unsigned token, unsigned stage, uint32_t result)
{
    uint32_t expected = 0;
    if (__atomic_compare_exchange_n(&fTx2IStats[16], &expected, 1U, false,
                                     __ATOMIC_ACQ_REL, __ATOMIC_RELAXED)) {
        __atomic_store_n(&fTx2IStats[17], token, __ATOMIC_RELAXED);
        __atomic_store_n(&fTx2IStats[18], stage, __ATOMIC_RELAXED);
        __atomic_store_n(&fTx2IStats[19], result, __ATOMIC_RELAXED);
        __atomic_store_n(&fTx2IStats[16], 2U, __ATOMIC_RELEASE);
        tx2IReport(3);
    }
}
bool ItlIwx::tx2IAllocate()
{
    fTx2IStats[0] = 1;
    for (unsigned i = 0; i < kTx2ICount; ++i) {
        unsigned stage = 0;
        IOReturn result = allocatePacketBacking2H(&fTx2I[i].dma, kTx2ISize, PAGE_SIZE, &stage);
        if (result != kIOReturnSuccess) {
            tx2IError(i + 1, stage, uint32_t(result)); return false;
        }
        __atomic_store_n(&fTx2I[i].state, uint32_t(Tx2IFree), __ATOMIC_RELEASE);
        ++fTx2IStats[2];
    }
    __atomic_store_n(&fTx2IReady, 1U, __ATOMIC_RELEASE);
    tx2IReport(1);
    return true;
}
int ItlIwx::tx2IPrepare(struct iwx_tx_data *data, mbuf_t packet, int qid, int idx,
                       IOPhysicalSegment *segments)
{
    __atomic_fetch_add(&fTx2IStats[3], 1U, __ATOMIC_RELAXED);
    if (__atomic_load_n(&fTx2IBlocked, __ATOMIC_ACQUIRE)) {
        __atomic_fetch_add(&fTx2IStats[8], 1U, __ATOMIC_RELAXED); return 0;
    }
    const size_t length = mbuf_pkthdr_len(packet);
    if (!length || length > kTx2ISize || data->m ||
        __atomic_load_n(&data->tx2I_token, __ATOMIC_ACQUIRE)) {
        __atomic_fetch_add(&fTx2IStats[10], 1U, __ATOMIC_RELAXED);
        tx2IError(0, 10, uint32_t(kIOReturnBadArgument)); return 0;
    }
    unsigned token = 0;
    for (unsigned n = 0; n < kTx2ICount; ++n) {
        const unsigned i = (fTx2INext + n) % kTx2ICount;
        uint32_t expected = Tx2IFree;
        if (__atomic_compare_exchange_n(&fTx2I[i].state, &expected, uint32_t(Tx2ICopying),
                                         false, __ATOMIC_ACQ_REL, __ATOMIC_RELAXED)) {
            token = i + 1; fTx2INext = (i + 1) % kTx2ICount; break;
        }
    }
    if (!token) {
        __atomic_fetch_add(&fTx2IStats[9], 1U, __ATOMIC_RELAXED);
        tx2IError(0, 11, uint32_t(kIOReturnNoResources)); return 0;
    }
    Tx2IBacking &backing = fTx2I[token - 1];
    __atomic_store_n(&backing.owner, data, __ATOMIC_RELEASE); backing.length = uint32_t(length);
    __atomic_store_n(&data->tx2I_token, uint16_t(token), __ATOMIC_RELEASE);
    // mbuf_copydata copies the complete final chain after encryption and trim;
    // it does not replace/free the mbuf or transfer the caller's node reference.
    const int copied = mbuf_copydata(packet, 0, length, backing.dma.vaddr);
    IOReturn result = copied ? kIOReturnError : backing.dma.cmd->synchronize(kIODirectionOut);
    if (copied || result != kIOReturnSuccess) {
        __atomic_fetch_add(&fTx2IStats[copied ? 11 : 12], 1U, __ATOMIC_RELAXED);
        tx2IError(token, copied ? 12 : 13, copied ? uint32_t(copied) : uint32_t(result));
        // Never published. A concurrent reset may already have quarantined it;
        // only our still-Copying state can be returned to the free pool.
        __atomic_exchange_n(&data->tx2I_token, uint16_t(0), __ATOMIC_ACQ_REL);
        uint32_t expected = Tx2ICopying;
        __atomic_store_n(&backing.owner, static_cast<iwx_tx_data *>(nullptr), __ATOMIC_RELEASE);
        __atomic_compare_exchange_n(&backing.state, &expected, uint32_t(Tx2IFree),
                                     false, __ATOMIC_ACQ_REL, __ATOMIC_RELAXED);
        return 0;
    }
    // Preserve the header's TB limit (4K-4), and never cross a page boundary.
    // All values derive from the single validated 8K IOVM extent, not the cursor.
    unsigned count = 0;
    for (size_t offset = 0; offset < length;) {
        const uint64_t address = backing.dma.paddr + offset;
        const size_t pageLeft = PAGE_SIZE - (address & (PAGE_SIZE - 1));
        const size_t bytes = MIN(length - offset, MIN(size_t(4092), pageLeft));
        segments[count].location = address; segments[count].length = bytes;
        ++count; offset += bytes;
    }
    uint32_t expected = Tx2ICopying;
    if (__atomic_load_n(&fTx2IBlocked, __ATOMIC_ACQUIRE) ||
        !__atomic_compare_exchange_n(&backing.state, &expected, uint32_t(Tx2IInflight),
                                      false, __ATOMIC_ACQ_REL, __ATOMIC_RELAXED)) {
        tx2IRetire(data, false); return 0;
    }
    __atomic_fetch_add(&fTx2IStats[4], 1U, __ATOMIC_RELAXED);
    uint32_t sampleExpected = 0;
    if (__atomic_compare_exchange_n(&fTx2IStats[20], &sampleExpected, 1U, false,
                                     __ATOMIC_ACQ_REL, __ATOMIC_RELAXED)) {
        __atomic_store_n(&fTx2IFirst[0], backing.dma.paddr, __ATOMIC_RELAXED);
        __atomic_store_n(&fTx2IFirst[1], uint64_t(length), __ATOMIC_RELAXED);
        __atomic_store_n(&fTx2IFirst[2], (uint64_t(uint32_t(qid)) << 32) | uint32_t(idx), __ATOMIC_RELAXED);
        __atomic_store_n(&fTx2IFirst[3], (uint64_t(token) << 32) | count, __ATOMIC_RELAXED);
        __atomic_store_n(&fTx2IStats[20], 2U, __ATOMIC_RELEASE);
    }
    return int(count);
}
void ItlIwx::tx2IPublished(struct iwx_tx_data *data)
{
    const uint32_t n = __atomic_add_fetch(&fTx2IStats[5], 1U, __ATOMIC_RELAXED);
    const unsigned kind = data->type == IEEE80211_FC0_TYPE_DATA ? 22 :
        (data->type == IEEE80211_FC0_TYPE_MGT ? 23 : 24);
    const uint32_t typed = __atomic_add_fetch(&fTx2IStats[kind], 1U, __ATOMIC_RELAXED);
    if (n == 1) __atomic_store_n(&fTx2IStats[29], uint32_t(data->type), __ATOMIC_RELAXED);
    if (n == 1 || n == 16 || n == 256 || n == 1024) tx2IReport(2);
    else if (kind == 22 && typed == 1) tx2IReport(7);
}

