static void awdlTxWinRetire(mbuf_t m, bool normal)
{
    const uintptr_t key = (uintptr_t)m;
    /* Reserve the slot while reading its metadata, so a new submission
     * cannot overwrite group/status before the retirement is accounted. */
    if (key <= 1 || !__sync_bool_compare_and_swap(&gAWDLTxWinKey, key, (uintptr_t)1))
        return;
    const UInt32 grp = __atomic_load_n(&gAWDLTxWinGroup, __ATOMIC_RELAXED);
    const UInt32 seen = __atomic_load_n(&gAWDLTxWinStatusSeen, __ATOMIC_RELAXED);
    if (normal) {
        if (grp == 1) __atomic_fetch_add(&gAWDLTxWinRetiredActive, 1U, __ATOMIC_RELAXED);
        else if (grp == 2) __atomic_fetch_add(&gAWDLTxWinRetiredInactive, 1U, __ATOMIC_RELAXED);
        if (!seen)
            __atomic_fetch_add(&gAWDLTxWinRetiredNoStatus, 1U, __ATOMIC_RELAXED);
    } else {
        __atomic_fetch_add(&gAWDLTxWinReset, 1U, __ATOMIC_RELAXED);
    }
    __atomic_store_n(&gAWDLTxWinKey, (uintptr_t)0, __ATOMIC_RELEASE);
}
