/* TXCTX-V1-COMPILEFIX: compare static model names without libc strstr.
 * This is only used on compiled-in, NUL-terminated product labels. */
static bool airplayTxCtxV1ModelHas(const char *model, const char *token)
{
    if (!model || !token || !*token)
        return false;
    for (const char *p = model; *p; ++p) {
        const char *a = p;
        const char *b = token;
        while (*a && *b && *a == *b) {
            ++a;
            ++b;
        }
        if (!*b)
            return true;
    }
    return false;
}
