void ItlIwx::tx2IRetire(struct iwx_tx_data *data, bool normal)
{
    const unsigned token = __atomic_exchange_n(&data->tx2I_token, uint16_t(0), __ATOMIC_ACQ_REL);
    if (!token) return;
    if (token > kTx2ICount || __atomic_load_n(&fTx2I[token - 1].owner, __ATOMIC_ACQUIRE) != data) {
        __atomic_fetch_or(&fTx2JAdmission, kTx2JClosed, __ATOMIC_ACQ_REL);
        __atomic_store_n(&fTx2IBlocked, 1U, __ATOMIC_RELEASE);
        tx2IError(token, 14, uint32_t(kIOReturnBadArgument)); return;
    }
    Tx2IBacking &backing = fTx2I[token - 1];
    uint32_t expected = Tx2IInflight;
    // IRQ TX/BA retirement and packet publication share the main workloop gate.
    // Ungated reset can win the token exchange; it always quarantines, never frees.
    if (normal && __atomic_compare_exchange_n(&backing.state, &expected, uint32_t(Tx2IFree),
                                               false, __ATOMIC_ACQ_REL, __ATOMIC_RELAXED)) {
        const uint32_t n = __atomic_add_fetch(&fTx2IStats[6], 1U, __ATOMIC_RELAXED);
        const unsigned kind = data->type == IEEE80211_FC0_TYPE_DATA ? 25 :
            (data->type == IEEE80211_FC0_TYPE_MGT ? 26 : 27);
        const uint32_t typed = __atomic_add_fetch(&fTx2IStats[kind], 1U, __ATOMIC_RELAXED);
        if (n == 1 || n == 16 || n == 256 || n == 1024) tx2IReport(4);
        else if (kind == 25 && typed == 1) tx2IReport(8);
        return;
    }
    __atomic_fetch_or(&fTx2JAdmission, kTx2JClosed, __ATOMIC_ACQ_REL);
    __atomic_store_n(&fTx2IBlocked, 1U, __ATOMIC_RELEASE);
    const uint32_t old = __atomic_exchange_n(&backing.state, uint32_t(Tx2IQuarantined), __ATOMIC_ACQ_REL);
    if (old != Tx2IQuarantined) {
        const uint32_t n = __atomic_add_fetch(&fTx2IStats[7], 1U, __ATOMIC_RELAXED);
        if (n == 1) tx2IReport(5);
    }
}
bool ItlIwx::tx2JEnter()
{
    if (!__atomic_load_n(&fTx2IReady, __ATOMIC_ACQUIRE) ||
        __atomic_load_n(&fTx2IBlocked, __ATOMIC_ACQUIRE)) return false;
    uint32_t value = __atomic_load_n(&fTx2JAdmission, __ATOMIC_ACQUIRE);
    do {
        if ((value & 0xffff0000U) || (value & 0xffffU) == 0xffffU) return false;
    } while (!__atomic_compare_exchange_n(&fTx2JAdmission, &value, value + 1U,
                                          false, __ATOMIC_ACQ_REL, __ATOMIC_ACQUIRE));
    return true;
}
void ItlIwx::tx2JLeave()
{
    __atomic_fetch_sub(&fTx2JAdmission, 1U, __ATOMIC_RELEASE);
}
bool ItlIwx::tx2IStop(unsigned origin)
{
    if (!__atomic_load_n(&fTx2IReady, __ATOMIC_ACQUIRE)) return false;
    // Close admission atomically before examining ownership. Nested scopes do
    // not reopen it until the outermost stop has returned. An active publisher
    // may be between its final software check and WRPTR: never infer a fence.
    const uint32_t prior = __atomic_fetch_add(&fTx2JAdmission, kTx2JStop, __ATOMIC_ACQ_REL);
    uint32_t copying = 0, inflight = 0, quarantined = 0;
    for (unsigned i = 0; i < kTx2ICount; ++i) {
        const uint32_t state = __atomic_load_n(&fTx2I[i].state, __ATOMIC_ACQUIRE);
        copying += state == Tx2ICopying;
        inflight += state == Tx2IInflight;
        quarantined += state == Tx2IQuarantined;
    }
    if ((prior & 0xffffU) || copying || inflight || quarantined) {
        __atomic_fetch_or(&fTx2JAdmission, kTx2JClosed, __ATOMIC_ACQ_REL);
        __atomic_store_n(&fTx2IBlocked, 1U, __ATOMIC_RELEASE);
    }
    flow2J(1, origin, copying, inflight, quarantined, prior & 0xffffU,
            __atomic_load_n(&fTx2IStats[5], __ATOMIC_RELAXED),
            __atomic_load_n(&fTx2IStats[6], __ATOMIC_RELAXED));
    return true;
}
void ItlIwx::tx2JStopEnd(bool entered, unsigned origin)
{
    if (!entered) return;
    __atomic_fetch_sub(&fTx2JAdmission, kTx2JStop, __ATOMIC_ACQ_REL);
    flow2J(2, origin, __atomic_load_n(&fTx2JAdmission, __ATOMIC_ACQUIRE),
            __atomic_load_n(&fTx2IBlocked, __ATOMIC_ACQUIRE), com.sc_generation);
    tx2IReport(6);
    flow2JPublish();
}
void ItlIwx::flow2J(unsigned event, unsigned code, uint32_t a, uint32_t b,
                    uint32_t c, uint32_t status, uint64_t address, uint64_t extra)
{
    // Post-pool RAM-only recording. No payload/SSID/key bytes or new hardware
    // reads. Nonwaiting exclusion: concurrent observations may be dropped.
    if (!__atomic_load_n(&fTx2IReady, __ATOMIC_ACQUIRE)) return;
    uint32_t expected = 0;
    if (!__atomic_compare_exchange_n(&fFlow2JBusy, &expected, 1U, false,
                                      __ATOMIC_ACQUIRE, __ATOMIC_RELAXED)) {
        __atomic_fetch_add(&fFlow2JDropped, 1U, __ATOMIC_RELAXED); return;
    }
    const Flow2JRecord record = {time2GNow(), event, code, a, b, c, status, address, extra};
    unsigned slot = fFlow2J.count;
    if (slot < 128) ++fFlow2J.count;
    else { slot = 127; ++fFlow2J.overflow; }
    fFlow2J.records[slot] = record;
    // Preserve first original operation failure, not stop user-count metadata.
    if (!fFlow2J.firstValid && ((status && (event == 9 || event == 14 || event == 18 || event == 20 || event == 21)) || event == 16)) {
        fFlow2J.firstFailure = record; fFlow2J.firstValid = 1;
    }
    __atomic_store_n(&fFlow2JBusy, 0U, __ATOMIC_RELEASE);
}
void ItlIwx::flow2JPublish()
{
    if (!__atomic_load_n(&fTx2IReady, __ATOMIC_ACQUIRE)) return;
    uint32_t expected = 0;
    if (!__atomic_compare_exchange_n(&fFlow2JBusy, &expected, 1U, false,
                                      __ATOMIC_ACQUIRE, __ATOMIC_RELAXED)) {
        __atomic_fetch_add(&fFlow2JDropped, 1U, __ATOMIC_RELAXED); return;
    }
    if (fFlow2J.snapshots >= 64) {
        __atomic_store_n(&fFlow2JBusy, 0U, __ATOMIC_RELEASE); return;
    }
    fFlow2J.schema = 1; fFlow2J.capacity = 128;
    fFlow2J.dropped = __atomic_load_n(&fFlow2JDropped, __ATOMIC_RELAXED);
    ++fFlow2J.snapshots;
    // OSData copies this member buffer while writer exclusion is held; no large
    // kernel-stack snapshot, allocation before pool setup, or provider retain.
    const bool ok = pci.pa_tag && pci.pa_tag->setProperty("KGP_FLOW_2J", &fFlow2J, sizeof(fFlow2J));
    if (!ok) ++fFlow2J.failures;
    __atomic_store_n(&fFlow2JBusy, 0U, __ATOMIC_RELEASE);
    XYLog("KGP_FLOW_2J published=%u\n", unsigned(ok));
}

void ItlIwx::tx2IFree()
{
    __atomic_fetch_or(&fTx2JAdmission, kTx2JClosed, __ATOMIC_ACQ_REL);
    __atomic_store_n(&fTx2IBlocked, 1U, __ATOMIC_RELEASE);
    for (unsigned i = 0; i < kTx2ICount; ++i) {
        uint32_t expected = Tx2IFree;
        if (__atomic_compare_exchange_n(&fTx2I[i].state, &expected, uint32_t(Tx2IEmpty),
                                         false, __ATOMIC_ACQ_REL, __ATOMIC_RELAXED)) {
            iwx_dma_contig_free(&fTx2I[i].dma);
            ++fTx2IStats[13];
        } else if (fTx2I[i].dma.cmd) {
            // Intentional bounded retention through HAL destruction. These are
            // standard SDK objects with no callback into this kext. Reboot is the
            // experiment's recovery boundary; never release an unproven mapping.
            ++fTx2IStats[21];
        }
    }
}


// 2L records values only. It never retries a gate, dequeues a second packet,
// changes an errno, reads hardware, or decides DMA ownership.
void ItlIwx::path2L(unsigned event, uint32_t result, uint32_t detail, uint32_t fc0)
{
    if (com.sc_device_family < IWX_DEVICE_FAMILY_AX210) return;
    uint32_t expected = 0;
    if (!__atomic_compare_exchange_n(&fPath2LBusy, &expected, 1U, false,
                                      __ATOMIC_ACQUIRE, __ATOMIC_RELAXED)) {
        __atomic_fetch_add(&fPath2LDropped, 1U, __ATOMIC_RELAXED); return;
    }
    auto &ic = com.sc_ic;
    Path2LRecord row = {};
    row.ns = time2GNow(); row.event = event; row.result = result;
    row.state = ic.ic_state; row.ifflags = ic.ic_if.if_flags;
    row.driverflags = com.sc_flags; row.qfull = com.qfullmsk;
    row.mgtlen = row.mgtdrops = UINT32_MAX;
    // Never wait for another thread's mbuf-queue lock just for telemetry.
    if (ic.ic_mgtq.mq_mtx && IORecursiveLockTryLock(ic.ic_mgtq.mq_mtx)) {
        row.mgtlen = mq_len(&ic.ic_mgtq); row.mgtdrops = mq_drops(&ic.ic_mgtq);
        IORecursiveLockUnlock(ic.ic_mgtq.mq_mtx);
    } else ++fPath2L.word[23];
    row.qid = uint32_t(com.first_data_qid);
    row.ringcount = row.ringqueued = UINT32_MAX;
    if (row.qid < nitems(com.txq)) {
        row.ringcount = com.txq[row.qid].ring_count;
        row.ringqueued = com.txq[row.qid].queued;
    }
    row.blocked = __atomic_load_n(&fTx2IBlocked, __ATOMIC_ACQUIRE);
    row.oactive = ic.ic_if.if_snd.ifq_oactive;
    row.generation = com.sc_generation; row.detail = detail; row.fc0 = fc0;
    fPath2L.word[0] = 1; ++fPath2L.word[2];
    const bool pending = row.mgtlen != UINT32_MAX && row.mgtlen != 0;
    const bool joining = row.state == IEEE80211_S_AUTH || row.state == IEEE80211_S_ASSOC;
    bool failure = false;
    switch (event) {
    case 1:
        ++fPath2L.word[4];
        if (!fPath2L.word[20] && (pending || joining)) {
            fPath2L.firstAttempt = row; fPath2L.word[20] = 1;
        }
        break;
    case 2:
        if (result) ++fPath2L.word[26];
        if (!detail) { ++fPath2L.word[6]; failure = pending || joining; }
        break;
    case 3: ++fPath2L.word[5]; break;
    case 4:
        if (detail >= 1 && detail <= 4) ++fPath2L.word[6 + detail];
        if (detail == 5) ++fPath2L.word[25];
        failure = detail >= 1 && detail <= 4 && (pending || joining);
        break;
    case 5: ++fPath2L.word[11]; break;
    case 6: ++fPath2L.word[12]; break;
    case 7:
        ++fPath2L.word[13];
        if (!fPath2L.word[22]) { fPath2L.firstTx = row; fPath2L.word[22] = 1; }
        break;
    case 8:
        ++fPath2L.word[result ? 15 : 14]; failure = result != 0;
        break;
    case 9: ++fPath2L.word[24]; break;
    }
    if (failure && !fPath2L.word[21]) {
        fPath2L.firstFailure = row; fPath2L.word[21] = 1;
    }
    fPath2L.latest = row;
    __atomic_store_n(&fPath2LBusy, 0U, __ATOMIC_RELEASE);
}
void ItlIwx::path2LPublish()
{
    if (com.sc_device_family < IWX_DEVICE_FAMILY_AX210) return;
    uint32_t expected = 0;
    if (!__atomic_compare_exchange_n(&fPath2LBusy, &expected, 1U, false,
                                      __ATOMIC_ACQUIRE, __ATOMIC_RELAXED)) return;
    // No snapshots for idle pre-join calls; preserve budget for the actual gap.
    if (!fPath2L.word[20] || fPath2L.word[1] >= 64) {
        __atomic_store_n(&fPath2LBusy, 0U, __ATOMIC_RELEASE); return;
    }
    ++fPath2L.word[1];
    fPath2L.word[3] = __atomic_load_n(&fPath2LDropped, __ATOMIC_RELAXED);
    fPath2L.word[17] = __atomic_load_n(&fTx2IStats[3], __ATOMIC_RELAXED);
    fPath2L.word[18] = __atomic_load_n(&fTx2IStats[5], __ATOMIC_RELAXED);
    fPath2L.word[19] = __atomic_load_n(&fTx2IStats[6], __ATOMIC_RELAXED);
    fPath2L.word[27] = __atomic_load_n(&fTx2IStats[4], __ATOMIC_RELAXED);
    fPath2L.word[28] = __atomic_load_n(&fTx2IStats[18], __ATOMIC_RELAXED);
    fPath2L.word[29] = __atomic_load_n(&fTx2IStats[19], __ATOMIC_RELAXED);
    fPath2L.word[30] = __atomic_load_n(&fTx2IBlocked, __ATOMIC_ACQUIRE);
    fPath2L.word[31] = 64;
    // Publish only after the original attemptAction returns. No packet or node
    // pointers are retained; the copied property survives normal HAL cleanup.
    if (fDrain2MLock) {
        for (unsigned i = 0; i < 24; ++i)
            fDrain2MWire[i] = __atomic_load_n(&fDrain2MStats[i], __ATOMIC_RELAXED);
        fDrain2MWire[0] = 1;
        const IOInterruptState irq = IOSimpleLockLockDisableInterrupt(fDrain2MLock);
        fDrain2MWire[14] = fDrain2MPending;
        fDrain2MWire[15] = fDrain2MPaused;
        fDrain2MWire[16] = fDrain2MClosed;
        fDrain2MWire[20] = fDrain2MEpoch;
        IOSimpleLockUnlockEnableInterrupt(fDrain2MLock, irq);
        fDrain2MWire[21] = fPath2L.word[1];
        if (!pci.pa_tag || !pci.pa_tag->setProperty("KGP_DRAIN_2M", fDrain2MWire, sizeof(fDrain2MWire)))
            __atomic_fetch_add(&fDrain2MStats[22], 1U, __ATOMIC_RELAXED);
    }
    const bool ok = pci.pa_tag && pci.pa_tag->setProperty("KGP_PATH_2L", &fPath2L, sizeof(fPath2L));
    if (!ok) ++fPath2L.word[16];
    const uint32_t snapshots = fPath2L.word[1], gate = fPath2L.word[6];
    const uint32_t dequeued = fPath2L.word[11], tx = fPath2L.word[13], errors = fPath2L.word[15];
    __atomic_store_n(&fPath2LBusy, 0U, __ATOMIC_RELEASE);
    XYLog("KGP_PATH_2L snapshot=%u gate_not_entered=%u mgmt_dequeued=%u tx_calls=%u tx_errors=%u\n",
          snapshots, gate, dequeued, tx, errors);
}

// 2M functional scheduling repair. No packet is copied/retained by this source.
// NULL provider means software events only (pinned IOInterruptEventSource.h).
bool ItlIwx::drain2MSetup()
{
    if (com.sc_device_family < IWX_DEVICE_FAMILY_AX210) return true;
    fDrain2MLock = IOSimpleLockAlloc();
    if (!fDrain2MLock) { fDrain2MStats[17] = kIOReturnNoMemory; return false; }
    fDrain2MEvent = IOInterruptEventSource::interruptEventSource(this, drain2MAction);
    if (!fDrain2MEvent) { fDrain2MStats[17] = kIOReturnNoMemory; return false; }
    const IOReturn result = getMainWorkLoop()->addEventSource(fDrain2MEvent);
    fDrain2MStats[17] = uint32_t(result);
    if (result != kIOReturnSuccess) {
        fDrain2MEvent->release(); fDrain2MEvent = nullptr; return false;
    }
    retain(); // callback owner stays alive until synchronous removal succeeds
    fDrain2MEvent->enable();
    return true;
}
void ItlIwx::drain2MRequest()
{
    if (!fDrain2MLock) return;
    __atomic_fetch_add(&fDrain2MStats[1], 1U, __ATOMIC_RELAXED);
    const IOInterruptState irq = IOSimpleLockLockDisableInterrupt(fDrain2MLock);
    if (!fDrain2MEvent || fDrain2MClosed || fDrain2MPaused) {
        __atomic_fetch_add(&fDrain2MStats[4], 1U, __ATOMIC_RELAXED);
    } else if (fDrain2MPending) {
        __atomic_fetch_add(&fDrain2MStats[3], 1U, __ATOMIC_RELAXED);
    } else {
        fDrain2MPending = true;
        __atomic_fetch_add(&fDrain2MStats[2], 1U, __ATOMIC_RELAXED);
        // Interrupt-safe producer signalling, not a gate acquisition or callout.
        // Removal first takes this lock, so the source cannot disappear here.
        fDrain2MEvent->interruptOccurred(nullptr, nullptr, 0);
    }
    IOSimpleLockUnlockEnableInterrupt(fDrain2MLock, irq);
}
IOReturn ItlIwx::drain2MFence(OSObject *, void *, void *, void *, void *)
{
    return kIOReturnSuccess;
}
uint32_t ItlIwx::drain2MPause()
{
    if (!fDrain2MLock) return 0;
    const IOInterruptState irq = IOSimpleLockLockDisableInterrupt(fDrain2MLock);
    fDrain2MPaused = true;
    const uint32_t epoch = ++fDrain2MEpoch;
    if (fDrain2MPending) __atomic_fetch_add(&fDrain2MStats[10], 1U, __ATOMIC_RELAXED);
    fDrain2MPending = false;
    IOSimpleLockUnlockEnableInterrupt(fDrain2MLock, irq);
    __atomic_fetch_add(&fDrain2MStats[11], 1U, __ATOMIC_RELAXED);
    // Lifecycle context only, BEFORE existing stop/admission/queue operations.
    // This empty workloop action fences an already-running deferred drain.
    // It never waits on a disabled command gate and holds no new lock while waiting.
    const IOReturn result = getMainWorkLoop()->runAction(drain2MFence, this);
    __atomic_store_n(&fDrain2MStats[18], uint32_t(result), __ATOMIC_RELAXED);
    return epoch;
}
void ItlIwx::drain2MArm(uint32_t epoch)
{
    if (!fDrain2MLock) return;
    const IOInterruptState irq = IOSimpleLockLockDisableInterrupt(fDrain2MLock);
    if (fDrain2MEvent && !fDrain2MClosed && epoch == fDrain2MEpoch)
        fDrain2MPaused = false;
    else __atomic_fetch_add(&fDrain2MStats[23], 1U, __ATOMIC_RELAXED);
    IOSimpleLockUnlockEnableInterrupt(fDrain2MLock, irq);
    __atomic_fetch_add(&fDrain2MStats[12], 1U, __ATOMIC_RELAXED);
}
void ItlIwx::drain2MRemove()
{
    if (!fDrain2MLock) return;
    const IOInterruptState irq = IOSimpleLockLockDisableInterrupt(fDrain2MLock);
    fDrain2MClosed = fDrain2MPaused = true;
    ++fDrain2MEpoch;
    if (fDrain2MPending) __atomic_fetch_add(&fDrain2MStats[10], 1U, __ATOMIC_RELAXED);
    fDrain2MPending = false;
    IOInterruptEventSource *source = fDrain2MEvent;
    fDrain2MEvent = nullptr;
    IOSimpleLockUnlockEnableInterrupt(fDrain2MLock, irq);
    if (!source) return;
    __atomic_fetch_add(&fDrain2MStats[13], 1U, __ATOMIC_RELAXED);
    source->disable();
    // SDK removal is synchronous with the workloop; no callback survives return.
    const IOReturn result = getMainWorkLoop()->removeEventSource(source);
    __atomic_store_n(&fDrain2MStats[19], uint32_t(result), __ATOMIC_RELAXED);
    if (result != kIOReturnSuccess) {
        // Unexpected contract failure: keep both owner/source alive, closed.
        // Never free an owner whose callback removal was not established.
        XYLog("KGP_DRAIN_2M removal failed=0x%x; closed owner retained\n", result);
        return;
    }
    source->release();
    release(); // paired setup retain; lifecycle caller still owns the HAL
}
void ItlIwx::drain2MAction(OSObject *owner, IOInterruptEventSource *sender, int)
{
    ItlIwx *that = static_cast<ItlIwx *>(owner);
    __atomic_fetch_add(&that->fDrain2MStats[5], 1U, __ATOMIC_RELAXED);
    const IOInterruptState irq = IOSimpleLockLockDisableInterrupt(that->fDrain2MLock);
    const bool claimed = sender == that->fDrain2MEvent && that->fDrain2MPending &&
                         !that->fDrain2MPaused && !that->fDrain2MClosed;
    if (claimed) that->fDrain2MPending = false;
    IOSimpleLockUnlockEnableInterrupt(that->fDrain2MLock, irq);
    if (!claimed) return;
    __atomic_fetch_add(&that->fDrain2MStats[6], 1U, __ATOMIC_RELAXED);
    Start2LContext context = {};
    // Already on the same recursive workloop gate: transient external gate
    // contention has ended. Still respect the original command-gate action.
    const IOReturn result = that->getMainCommandGate()->attemptAction(
        _iwx_start_task, &that->com.sc_ic.ic_ac.ac_if, &context);
    __atomic_fetch_add(&that->fDrain2MStats[context.entered ? 7 : 8], 1U, __ATOMIC_RELAXED);
    __atomic_store_n(&that->fDrain2MStats[9], uint32_t(result), __ATOMIC_RELAXED);
    that->path2L(2, uint32_t(result), context.entered ? 1U : 0U);
    that->path2LPublish();
    // No self-rescheduling loop. Another enqueue can signal new work; normal
    // backpressure remains governed by the unchanged queue/completion paths.
}

// 2K: command-queue backing is separate from RX and ordinary TX. One cached
// prepared page per command index, allocated only after final command bytes
// exist. No index is reused until BOTH the original caller and CmdDone finish.
bool ItlIwx::cmd2KAvailable(unsigned idx)
{
    return idx < kCmd2KCount && !__atomic_load_n(&fCmd2KFrozen, __ATOMIC_SEQ_CST) &&
        !__atomic_load_n(&fCmd2KResetDepth, __ATOMIC_SEQ_CST) &&
        __atomic_load_n(&fCmd2K[idx].state, __ATOMIC_SEQ_CST) == Cmd2KFree;
}
bool ItlIwx::cmd2KClaim(unsigned idx, uint32_t code, uint32_t generation,
                         uint32_t epoch, uint32_t *serial)
{
    if (!cmd2KAvailable(idx)) return false;
    auto &b = fCmd2K[idx];
    uint32_t expected = Cmd2KFree;
    if (!__atomic_compare_exchange_n(&b.state, &expected, uint32_t(Cmd2KCopying),
                                      false, __ATOMIC_SEQ_CST, __ATOMIC_SEQ_CST)) return false;
    *serial = __atomic_add_fetch(&b.serial, 1U, __ATOMIC_SEQ_CST);
    __atomic_store_n(&b.code, code, __ATOMIC_SEQ_CST);
    __atomic_store_n(&b.generation, generation, __ATOMIC_SEQ_CST);
    __atomic_store_n(&b.callerDone, 0U, __ATOMIC_SEQ_CST);
    __atomic_store_n(&b.packet, mbuf_t(nullptr), __ATOMIC_SEQ_CST);
    if (epoch != __atomic_load_n(&fCmd2KEpoch, __ATOMIC_SEQ_CST) ||
        __atomic_load_n(&fCmd2KResetDepth, __ATOMIC_SEQ_CST) ||
        __atomic_load_n(&fCmd2KFrozen, __ATOMIC_SEQ_CST)) {
        expected = Cmd2KCopying;
        __atomic_compare_exchange_n(&b.state, &expected, uint32_t(Cmd2KFree),
                                     false, __ATOMIC_SEQ_CST, __ATOMIC_SEQ_CST);
        return false;
    }
    return true;
}
void ItlIwx::cmd2KQuarantine(unsigned idx)
{
    auto &b = fCmd2K[idx];
    uint32_t state = __atomic_load_n(&b.state, __ATOMIC_SEQ_CST);
    while (state == Cmd2KCopying || state == Cmd2KInflight || state == Cmd2KCompleting) {
        if (__atomic_compare_exchange_n(&b.state, &state, uint32_t(Cmd2KQuarantined),
                                         false, __ATOMIC_SEQ_CST, __ATOMIC_SEQ_CST)) {
            __atomic_fetch_add(&fCmd2KStats[7], 1U, __ATOMIC_RELAXED); break;
        }
    }
    if (__atomic_load_n(&b.state, __ATOMIC_SEQ_CST) == Cmd2KQuarantined) {
        /* CMDTHAW-20261105: make the freeze visible in the flag dump. */
        if (!__atomic_exchange_n(&fCmd2KFrozen, 1U, __ATOMIC_SEQ_CST)) {
            const uint32_t f = __atomic_add_fetch(&fCmd2KStats[29], 1U, __ATOMIC_RELAXED);
            if (IOEthernetController *ctl = getController()) {
                ctl->setProperty("AIRPLAYCmd2KFrozen", (unsigned long long)1, 32);
                ctl->setProperty("AIRPLAYCmd2KFreezeEvents", (unsigned long long)f, 32);
                ctl->setProperty("AIRPLAYCmd2KFreezeLastSlot", (unsigned long long)idx, 32);
            }
        }
    }
}
void ItlIwx::cmd2KError(unsigned idx, unsigned stage, uint32_t status)
{
    uint32_t expected = 0;
    if (__atomic_compare_exchange_n(&fCmd2KStats[12], &expected, 1U, false,
                                     __ATOMIC_ACQ_REL, __ATOMIC_RELAXED)) {
        __atomic_store_n(&fCmd2KStats[13], stage, __ATOMIC_RELAXED);
        __atomic_store_n(&fCmd2KStats[14], status, __ATOMIC_RELAXED);
        __atomic_store_n(&fCmd2KStats[15], idx, __ATOMIC_RELAXED);
        __atomic_store_n(&fCmd2KStats[12], 2U, __ATOMIC_RELEASE);
    }
}
int ItlIwx::cmd2KPrepare(unsigned idx, uint32_t serial, uint32_t epoch, mbuf_t packet,
                         size_t length, iwx_tx_data *data, bool *linked,
                         uint64_t *address, void **bytes)
{
    auto &b = fCmd2K[idx];
    if (length > kCmd2KSize || length <= sizeof(iwx_cmd_header_wide) ||
        __atomic_load_n(&b.serial, __ATOMIC_SEQ_CST) != serial) {
        cmd2KError(idx, 8, kIOReturnBadArgument); return EINVAL;
    }
    if (!b.dma.cmd) {
        unsigned stage = 0;
        IOReturn result = allocatePacketBacking2H(&b.dma, kCmd2KSize, PAGE_SIZE, &stage);
        if (result != kIOReturnSuccess) { cmd2KError(idx, stage, uint32_t(result)); return ENOMEM; }
        __atomic_fetch_add(&fCmd2KStats[2], 1U, __ATOMIC_RELAXED);
    }
    __atomic_store_n(&b.observedAddress, uint64_t(b.dma.paddr), __ATOMIC_SEQ_CST);
    __atomic_store_n(&b.length, uint32_t(length), __ATOMIC_SEQ_CST);
    const int copied = mbuf_copydata(packet, 0, length, b.dma.vaddr);
    if (copied) {
        __atomic_fetch_add(&fCmd2KStats[9], 1U, __ATOMIC_RELAXED);
        cmd2KError(idx, 9, uint32_t(copied)); return ENOMEM;
    }
    const IOReturn synced = b.dma.cmd->synchronize(kIODirectionOut);
    if (synced != kIOReturnSuccess) {
        __atomic_fetch_add(&fCmd2KStats[10], 1U, __ATOMIC_RELAXED);
        cmd2KError(idx, 10, uint32_t(synced)); return ENOMEM;
    }
    __atomic_fetch_add(&fCmd2KStats[3], 1U, __ATOMIC_RELAXED);
    // Reset closes admission/increments epoch before inspecting states. A reset
    // either sees this Copying/Inflight state or makes the checks below fail.
    if (__atomic_load_n(&fCmd2KFrozen, __ATOMIC_SEQ_CST) ||
        __atomic_load_n(&fCmd2KResetDepth, __ATOMIC_SEQ_CST) ||
        epoch != __atomic_load_n(&fCmd2KEpoch, __ATOMIC_SEQ_CST) ||
        int(__atomic_load_n(&b.generation, __ATOMIC_SEQ_CST)) != com.sc_generation) return ENXIO;
    __atomic_store_n(&b.packet, packet, __ATOMIC_SEQ_CST);
    mbuf_t empty = nullptr;
    if (!__atomic_compare_exchange_n(&data->m, &empty, packet, false,
                                      __ATOMIC_SEQ_CST, __ATOMIC_SEQ_CST)) {
        cmd2KError(idx, 11, kIOReturnBusy); return EBUSY;
    }
    *linked = true; // reset/CmdDone now share the original mbuf disposition.
    uint32_t expected = Cmd2KCopying;
    if (!__atomic_compare_exchange_n(&b.state, &expected, uint32_t(Cmd2KInflight),
                                      false, __ATOMIC_SEQ_CST, __ATOMIC_SEQ_CST)) return ENXIO;
    *address = b.dma.paddr; *bytes = b.dma.vaddr;
    cmd2KObserve(1, idx);
    return 0;
}
void ItlIwx::cmd2KFinish(unsigned idx, uint32_t serial, bool published, int result)
{
    auto &b = fCmd2K[idx];
    if (__atomic_load_n(&b.serial, __ATOMIC_SEQ_CST) != serial) return;
    if (published) {
        __atomic_fetch_add(&fCmd2KStats[4], 1U, __ATOMIC_RELAXED);
        if (__atomic_load_n(&b.code, __ATOMIC_SEQ_CST) == 0x010d)
            __atomic_fetch_add(&fCmd2KStats[22], 1U, __ATOMIC_RELAXED);
        if (result == EWOULDBLOCK) __atomic_fetch_add(&fCmd2KStats[24], 1U, __ATOMIC_RELAXED);
        if (result == ENXIO) __atomic_fetch_add(&fCmd2KStats[25], 1U, __ATOMIC_RELAXED);
        // A concurrently accepted CmdDone is positive evidence; timeout alone
        // cannot make a still-Inflight entry Free. Late ack after quarantine is
        // intentionally not used to recover this experimental attachment.
        if (result && __atomic_load_n(&b.state, __ATOMIC_SEQ_CST) == Cmd2KInflight)
            cmd2KQuarantine(idx);
    } else {
        uint32_t expected = Cmd2KCopying;
        __atomic_compare_exchange_n(&b.state, &expected, uint32_t(Cmd2KFree),
                                     false, __ATOMIC_SEQ_CST, __ATOMIC_SEQ_CST);
    }
    cmd2KObserve(published ? 2 : 3, idx, uint32_t(result));
    __atomic_store_n(&b.callerDone, 1U, __ATOMIC_SEQ_CST);
    uint32_t expected = Cmd2KDone;
    if (__atomic_compare_exchange_n(&b.state, &expected, uint32_t(Cmd2KFree),
                                     false, __ATOMIC_SEQ_CST, __ATOMIC_SEQ_CST))
        __atomic_fetch_add(&fCmd2KStats[6], 1U, __ATOMIC_RELAXED);
    cmd2KReport(published ? 2 : 3);
}
int ItlIwx::cmd2KDone(unsigned idx, int code, iwx_tx_data *data)
{
    if (idx >= kCmd2KCount) return -1;
    auto &b = fCmd2K[idx];
    uint32_t state = __atomic_load_n(&b.state, __ATOMIC_SEQ_CST);
    if (state == Cmd2KFree) return 0; // original inline/other command behavior.
    if (state != Cmd2KInflight ||
        uint32_t(code) != __atomic_load_n(&b.code, __ATOMIC_SEQ_CST) ||
        int(__atomic_load_n(&b.generation, __ATOMIC_SEQ_CST)) != com.sc_generation ||
        __atomic_load_n(&data->m, __ATOMIC_SEQ_CST) != __atomic_load_n(&b.packet, __ATOMIC_SEQ_CST) ||
        !__atomic_compare_exchange_n(&b.state, &state, uint32_t(Cmd2KCompleting),
                                      false, __ATOMIC_SEQ_CST, __ATOMIC_SEQ_CST)) {
        __atomic_fetch_add(&fCmd2KStats[18], 1U, __ATOMIC_RELAXED);
        cmd2KQuarantine(idx); cmd2KObserve(5, idx, uint32_t(code)); cmd2KReport(5);
        return -1;
    }
    __atomic_fetch_add(&fCmd2KStats[5], 1U, __ATOMIC_RELAXED);
    if (uint32_t(code) == 0x010d) __atomic_fetch_add(&fCmd2KStats[23], 1U, __ATOMIC_RELAXED);
    return 1;
}
void ItlIwx::cmd2KDoneEnd(unsigned idx)
{
    auto &b = fCmd2K[idx];
    cmd2KObserve(4, idx);
    uint32_t expected = Cmd2KCompleting;
    if (__atomic_compare_exchange_n(&b.state, &expected, uint32_t(Cmd2KDone),
                                     false, __ATOMIC_SEQ_CST, __ATOMIC_SEQ_CST) &&
        __atomic_load_n(&b.callerDone, __ATOMIC_SEQ_CST)) {
        expected = Cmd2KDone;
        if (__atomic_compare_exchange_n(&b.state, &expected, uint32_t(Cmd2KFree),
                                         false, __ATOMIC_SEQ_CST, __ATOMIC_SEQ_CST))
            __atomic_fetch_add(&fCmd2KStats[6], 1U, __ATOMIC_RELAXED);
    }
    cmd2KReport(4);
}
void ItlIwx::cmd2KResetBegin()
{
    __atomic_fetch_add(&fCmd2KResetDepth, 1U, __ATOMIC_SEQ_CST);
    __atomic_fetch_add(&fCmd2KEpoch, 1U, __ATOMIC_SEQ_CST);
    __atomic_fetch_add(&fCmd2KStats[21], 1U, __ATOMIC_RELAXED);
    for (unsigned i = 0; i < kCmd2KCount; ++i) cmd2KQuarantine(i);
}
void ItlIwx::cmd2KResetEnd()
{
    __atomic_fetch_sub(&fCmd2KResetDepth, 1U, __ATOMIC_SEQ_CST);
}
/*
 * CMDTHAW-20261105
 * Bug: a Wi-Fi power-off (iwx_stop_device) while ANY command slot is
 * Copying/Inflight/Completing quarantines that slot and sets fCmd2KFrozen.
 * Nothing ever cleared it, so cmd2KAvailable() stayed false forever: every
 * firmware command returned EBUSY, iwx_init() failed with 16, ic_state stayed
 * INIT and setSCAN_REQ rejected every scan (AIRPLAYSCANRejectInit) -> "no
 * networks" until reboot.
 *
 * The quarantine exists so firmware can never DMA into a reused page. Once
 * iwx_stop_device() has POSITIVELY stopped the PCIe bus master and reset the
 * on-board processor (inside the workloop gate), the firmware that owned those
 * pages no longer exists. Only then: retire every non-Free slot, abandon (leak,
 * never free/reuse) its DMA page, bump its serial so any late caller's
 * cmd2KFinish() is a no-op, and reopen admission. If the master stop is not
 * positive, this is never called and the freeze stays as before.
 */
void ItlIwx::cmd2KThawAfterPositiveReset()
{
    uint32_t thawed = 0, leaked = 0;
    const uint32_t wasFrozen = __atomic_load_n(&fCmd2KFrozen, __ATOMIC_SEQ_CST);
    for (unsigned i = 0; i < kCmd2KCount; ++i) {
        auto &b = fCmd2K[i];
        if (__atomic_load_n(&b.state, __ATOMIC_SEQ_CST) == Cmd2KFree) continue;
        __atomic_add_fetch(&b.serial, 1U, __ATOMIC_SEQ_CST);
        __atomic_store_n(&b.packet, mbuf_t(nullptr), __ATOMIC_SEQ_CST);
        if (b.dma.cmd) { memset(&b.dma, 0, sizeof(b.dma)); ++leaked; }
        __atomic_store_n(&b.callerDone, 0U, __ATOMIC_SEQ_CST);
        __atomic_store_n(&b.state, uint32_t(Cmd2KFree), __ATOMIC_SEQ_CST);
        ++thawed;
    }
    __atomic_store_n(&fCmd2KFrozen, 0U, __ATOMIC_SEQ_CST);
    const uint32_t calls = __atomic_add_fetch(&fCmd2KStats[30], 1U, __ATOMIC_RELAXED);
    uint32_t thaws = __atomic_load_n(&fCmd2KStats[31], __ATOMIC_RELAXED);
    if (wasFrozen || thawed) thaws = __atomic_add_fetch(&fCmd2KStats[31], 1U, __ATOMIC_RELAXED);
    static volatile UInt32 leakedTotal = 0, slotsTotal = 0;
    const UInt32 lt = __sync_add_and_fetch(&leakedTotal, leaked);
    const UInt32 st = __sync_add_and_fetch(&slotsTotal, thawed);
    if (IOEthernetController *ctl = getController()) {
        ctl->setProperty("AIRPLAYCmd2KFrozen", (unsigned long long)0, 32);
        ctl->setProperty("AIRPLAYCmd2KThawChecks", (unsigned long long)calls, 32);
        ctl->setProperty("AIRPLAYCmd2KThawEvents", (unsigned long long)thaws, 32);
        ctl->setProperty("AIRPLAYCmd2KThawSlots", (unsigned long long)st, 32);
        ctl->setProperty("AIRPLAYCmd2KThawLeakedPages", (unsigned long long)lt, 32);
        ctl->setProperty("AIRPLAYCmd2KThawLastWasFrozen", (unsigned long long)wasFrozen, 32);
    }
    if (wasFrozen || thawed)
        XYLog("AIRPLAY CMDTHAW: wasFrozen=%u slots=%u leakedPages=%u events=%u\n",
              wasFrozen, thawed, leaked, thaws);
}
void ItlIwx::cmd2KFree()
{
    for (unsigned i = 0; i < kCmd2KCount; ++i) {
        if (__atomic_load_n(&fCmd2K[i].state, __ATOMIC_SEQ_CST) == Cmd2KFree) {
            if (fCmd2K[i].dma.cmd) { iwx_dma_contig_free(&fCmd2K[i].dma); ++fCmd2KStats[17]; }
        } else if (fCmd2K[i].dma.cmd) ++fCmd2KStats[16];
    }
}
void ItlIwx::cmd2KObserve(unsigned event, unsigned idx, uint32_t status)
{
    uint32_t expected = 0;
    if (!__atomic_compare_exchange_n(&fCmd2KDiagBusy, &expected, 1U, false,
                                      __ATOMIC_ACQUIRE, __ATOMIC_RELAXED)) {
        __atomic_fetch_add(&fCmd2KStats[27], 1U, __ATOMIC_RELAXED); return;
    }
    auto &b = fCmd2K[idx];
    const uint32_t serial = __atomic_load_n(&b.serial, __ATOMIC_SEQ_CST);
    uint64_t row[8] = {time2GNow(), __atomic_load_n(&b.observedAddress, __ATOMIC_SEQ_CST),
        __atomic_load_n(&b.length, __ATOMIC_SEQ_CST),
        (uint64_t(__atomic_load_n(&b.code, __ATOMIC_SEQ_CST)) << 32) | idx,
        (uint64_t(__atomic_load_n(&b.generation, __ATOMIC_SEQ_CST)) << 32) | serial,
        (uint64_t(event) << 32) | __atomic_load_n(&b.state, __ATOMIC_SEQ_CST), status, 1};
    if (serial != __atomic_load_n(&b.serial, __ATOMIC_SEQ_CST)) row[7] = 0;
    memcpy(fCmd2KLast, row, sizeof(row));
    if (event == 1 && !fCmd2KFirst[7]) memcpy(fCmd2KFirst, row, sizeof(row));
    __atomic_store_n(&fCmd2KDiagBusy, 0U, __ATOMIC_RELEASE);
}
void ItlIwx::cmd2KReport(unsigned reason)
{
    uint32_t expected = 0;
    if (!__atomic_compare_exchange_n(&fCmd2KDiagBusy, &expected, 1U, false,
                                      __ATOMIC_ACQUIRE, __ATOMIC_RELAXED)) return;
    if (fCmd2KStats[26] >= 64) { __atomic_store_n(&fCmd2KDiagBusy, 0U, __ATOMIC_RELEASE); return; }
    struct { uint32_t word[32]; uint64_t first[8], last[8]; } wire = {};
    const uint32_t firstError = __atomic_load_n(&fCmd2KStats[12], __ATOMIC_ACQUIRE);
    for (unsigned i = 0; i < 32; ++i) wire.word[i] = __atomic_load_n(&fCmd2KStats[i], __ATOMIC_RELAXED);
    wire.word[0] = 1; wire.word[1] = reason;
    wire.word[11] = __atomic_load_n(&fCmd2KFrozen, __ATOMIC_SEQ_CST);
    wire.word[12] = firstError;
    if (firstError != 2) wire.word[13] = wire.word[14] = wire.word[15] = 0;
    wire.word[26] = ++fCmd2KStats[26];
    memcpy(wire.first, fCmd2KFirst, sizeof(wire.first)); memcpy(wire.last, fCmd2KLast, sizeof(wire.last));
    const bool ok = pci.pa_tag && pci.pa_tag->setProperty("KGP_CMD_2K", &wire, sizeof(wire));
    if (!ok) ++fCmd2KStats[20];
    __atomic_store_n(&fCmd2KDiagBusy, 0U, __ATOMIC_RELEASE);
    XYLog("KGP_CMD_2K reason=%u mapped=%u copied=%u submitted=%u done=%u quarantined=%u frozen=%u\n",
          reason, wire.word[2], wire.word[3], wire.word[4], wire.word[5], wire.word[7], wire.word[11]);
}


/*
 * Sonoma AX210 RX cache fix.
 *
 * Preserve the current KGP prepared-DMA architecture and the generic
 * uncached allocator used by TX/command backing.
 *
 * RX receives into its own prepared slot backing and is then CPU-read
 * and copied into the mbuf.  For RX only, use the same current allocator
 * implementation with kIOMapInhibitCache removed.
 *
 * synchronize(kIODirectionIn), ownership, IOVM mapping, alignment,
 * descriptor publication and lifetime remain unchanged.
 */
static IOReturn allocateRxBacking2H(struct iwx_dma_info *dma, size_t size,
                                        unsigned alignment, unsigned *stage)
{
    *stage = 1;
    IOBufferMemoryDescriptor *bmd = IOBufferMemoryDescriptor::inTaskWithPhysicalMask(
        kernel_task, kIODirectionInOut | kIOMemoryPhysicallyContiguous,
        size, DMA_BIT_MASK(64));
    if (!bmd) return kIOReturnNoMemory;
    *stage = 2;
    IOReturn result = bmd->prepare();
    if (result != kIOReturnSuccess) { bmd->release(); return result; }
    *stage = 3;
    IODMACommand *cmd = IODMACommand::withSpecification(kIODMACommandOutputHost64,
        64, 0, IODMACommand::kMapped, 0, alignment);
    if (!cmd) { bmd->complete(); bmd->release(); return kIOReturnNoMemory; }
    *stage = 4;
    result = cmd->setMemoryDescriptor(bmd);
    if (result != kIOReturnSuccess) {
        cmd->clearMemoryDescriptor(); cmd->release(); bmd->complete(); bmd->release(); return result;
    }
    *stage = 5;
    UInt64 offset = 0;
    UInt32 count = 1;
    IODMACommand::Segment64 seg = {};
    result = cmd->gen64IOVMSegments(&offset, &seg, &count);
    if (result == kIOReturnSuccess && (count != 1 || offset != size || seg.fLength != size ||
        !alignment || (seg.fIOVMAddr & (alignment - 1)) || !bmd->getBytesNoCopy())) {
        *stage = 6;
        result = kIOReturnBadArgument;
    }
    if (result != kIOReturnSuccess) {
        cmd->clearMemoryDescriptor(); cmd->release(); bmd->complete(); bmd->release(); return result;
    }
    void *bytes = bmd->getBytesNoCopy();
    memset(bytes, 0, size);
    *stage = 7;
    result = cmd->synchronize(kIODirectionOut);
    if (result != kIOReturnSuccess) {
        cmd->clearMemoryDescriptor(); cmd->release(); bmd->complete(); bmd->release(); return result;
    }
    dma->paddr = seg.fIOVMAddr;
    dma->vaddr = bytes;
    dma->size = size;
    dma->buffer = bmd;
    dma->cmd = cmd;
    *stage = 0;
    return kIOReturnSuccess;
}

bool ItlIwx::rx2HAllocate(unsigned slot)
{
    fRxMap2H[0] = 1;
    fRxMap2H[1] = 1;
    unsigned stage;
    IOReturn result = allocateRxBacking2H(&fRxBacking2H[slot], IWX_RBUF_SIZE, PAGE_SIZE, &stage);
    if (result != kIOReturnSuccess) { rx2HError(slot, stage, result); return false; }
    __atomic_fetch_add(&fRxMap2H[2], 1U, __ATOMIC_RELAXED);
    return true;
}

bool ItlIwx::rx2HCopy(unsigned slot, mbuf_t packet)
{
    __atomic_fetch_add(&fRxMap2H[7], 1U, __ATOMIC_RELAXED);
    if (slot >= IWX_RX_MQ_RING_COUNT || !packet || !mbuf_data(packet) ||
        mbuf_len(packet) < IWX_RBUF_SIZE || !fRxBacking2H[slot].cmd ||
        !fRxBacking2H[slot].vaddr || fRxBacking2H[slot].size != IWX_RBUF_SIZE) {
        __atomic_fetch_add(&fRxMap2H[11], 1U, __ATOMIC_RELAXED);
        rx2HError(slot, 8, kIOReturnBadArgument); return false;
    }
    // Existing RX completion/cur selection is the hardware ownership boundary.
    // This synchronizes prepared command buffers, not a new mapping or DMA fence.
    IOReturn result = fRxBacking2H[slot].cmd->synchronize(kIODirectionIn);
    if (result != kIOReturnSuccess) {
        __atomic_fetch_add(&fRxMap2H[10], 1U, __ATOMIC_RELAXED);
        rx2HError(slot, 9, result); return false;
    }
    memcpy(mbuf_data(packet), fRxBacking2H[slot].vaddr, IWX_RBUF_SIZE);
    __atomic_fetch_add(&fRxMap2H[8], 1U, __ATOMIC_RELAXED);
    return true;
}

bool ItlIwx::alive2FOwned() const
{
    return fAlive2FOwner == current_thread();
}
void ItlIwx::alive2FStep(uint32_t stage)
{
    if (!alive2FOwned()) return;
    fAlive2F.word[1] = stage;
    fAlive2F.word[56] |= 1U << stage;
}
int ItlIwx::alive2FResult(uint32_t stage, int result)
{
    if (alive2FOwned()) {
        alive2FStep(stage);
        if (result && !fAlive2F.word[2]) {
            fAlive2F.word[2] = stage;
            fAlive2F.word[3] = static_cast<uint32_t>(result);
        }
    }
    return result;
}
void ItlIwx::alive2FEvent(unsigned index)
{
    if (__atomic_load_n(&fAlive2FPhase, __ATOMIC_RELAXED))
        __atomic_fetch_add(&fAlive2FEvents[index], 1U, __ATOMIC_RELAXED);
}
void ItlIwx::alive2FSnapshot(unsigned offset)
{
    for (unsigned i = 0; i < 12; ++i)
        fAlive2F.word[offset + i] = __atomic_load_n(&fAlive2FEvents[i], __ATOMIC_RELAXED);
}
uint16_t ItlIwx::alive2FStatus(uint16_t status)
{
    const uint32_t phase = __atomic_load_n(&fAlive2FPhase, __ATOMIC_RELAXED);
    if (phase) {
        uint32_t expected = 0;
        __atomic_compare_exchange_n(&fAlive2FEvents[7], &expected, phase, false,
                                    __ATOMIC_RELAXED, __ATOMIC_RELAXED);
        __atomic_store_n(&fAlive2FEvents[8], static_cast<uint32_t>(status), __ATOMIC_RELAXED);
        alive2FEvent(6);
    }
    return status;
}
void ItlIwx::alive2FTerminal(IOPCIDevice *provider, bool attached)
{
    fTime2G[11] = time2GNow();
    __atomic_store_n(&fAlive2FPhase, 0U, __ATOMIC_RELAXED);
    alive2FSnapshot(44);
    rx2GSnapshot();
    fAlive2F.word[4] = attached;
    alive2FStep(10);
    fAlive2FOwner = nullptr;
    // Bounded OSData copies after original attach cleanup/preinit stop.
    // No string formatting buffer, explicit arbitration, first-property lookup,
    // automatic destructor, or free()/stop() publication is introduced.
    if (fAlive2F.word[56] & (1U << 4)) {
        IOLog("itlwm: KGP_ALIVE_2H wait ret=0x%08x uc_pre=%u/%u uc_post=%u/%u irq=%u/%u alive=%u phase=%u status=0x%x wake=%u\n",
              fAlive2F.word[6], fAlive2F.word[7], fAlive2F.word[8], fAlive2F.word[9], fAlive2F.word[10],
              fAlive2F.word[32], fAlive2F.word[33], fAlive2F.word[38], fAlive2F.word[39],
              fAlive2F.word[40], fAlive2F.word[41]);
        IOLog("itlwm: KGP_ALIVE_2H path r1=0x%08x r2=0x%08x notif=%u packets=%u csr_alive=%u sec=%u cpu1=0x%x cpu2=0x%x pc=0x%x/0x%x\n",
              fAlive2F.word[34], fAlive2F.word[35], fAlive2F.word[36], fAlive2F.word[37],
              fAlive2F.word[43], fAlive2F.word[11], fAlive2F.word[12], fAlive2F.word[13],
              fAlive2F.word[14], fAlive2F.word[15]);
    }
    fTime2G[12] = time2GNow();
    const bool published = provider->setProperty("KGP_ALIVE_2H", &fAlive2F, sizeof(fAlive2F));
    const bool rxPublished = provider->setProperty("KGP_RX_2H", &fRx2GWire, sizeof(fRx2GWire));
    const uint32_t firstState2H = __atomic_load_n(&fRxMap2H[3], __ATOMIC_ACQUIRE);
    for (unsigned i = 0; i < 16; ++i)
        fRxMapWire2H[i] = __atomic_load_n(&fRxMap2H[i], __ATOMIC_RELAXED);
    fRxMapWire2H[3] = firstState2H;
    if (firstState2H != 2) fRxMapWire2H[4] = fRxMapWire2H[5] = fRxMapWire2H[6] = 0;
    const bool mapPublished2H = provider->setProperty("KGP_RXMAP_2H", fRxMapWire2H, sizeof(fRxMapWire2H));
    const bool detachPublished2H = provider->setProperty("KGP_DETACH_2H", fDetach2H, sizeof(fDetach2H));
    fTime2G[13] = time2GNow();
    const bool timePublished = provider->setProperty("KGP_TIME_2H", fTime2G, sizeof(fTime2G));
    IOLog("itlwm: KGP_RXMAP_2H allocated=%u copied=%u/%u first=%u slot=%u stage=%u code=0x%x freed=%u properties=%u/%u\n",
          fRxMapWire2H[2], fRxMapWire2H[8], fRxMapWire2H[7], fRxMapWire2H[3], fRxMapWire2H[4],
          fRxMapWire2H[5], fRxMapWire2H[6], fRxMapWire2H[9], unsigned(mapPublished2H), unsigned(detachPublished2H));
    IOLog("itlwm: KGP_RX_2H terminal total=%u stored=%u property=%u time_property=%u at_ns=%llu\n",
          fRx2GWire.header[1], fRx2GWire.header[2], unsigned(rxPublished), unsigned(timePublished), (unsigned long long)time2GNow());
    IOLog("itlwm: KGP_ALIVE_2H terminal schema=1 attach=%u first=%u code=0x%08x property=%u cleanup-returned=%u\n",
          unsigned(attached), fAlive2F.word[2], fAlive2F.word[3], unsigned(published), unsigned(!attached));
}

bool ItlIwx::attach(IOPCIDevice *device)
{
    const bool captureAttach2G = fAlive2F.word[0] == 0;
    if (captureAttach2G) {
        fAlive2FOwner = current_thread();
        fTime2G[0] = 1;
        time2GMark(1);
        fAlive2F.word[0] = 1;
    }
    alive2FStep(1);
    pci.pa_tag = device;
    pci.workloop = getMainWorkLoop();
    const bool attached2G = iwx_attach(&com, &pci);
    time2GMark(8);
    if (!attached2G) {
        alive2FResult(1, -1); // Synthetic outer Boolean failure; first error wins.
        alive2FStep(9);
        detach(device);
        time2GMark(9);
        releaseAll();
        time2GMark(10);
        if (captureAttach2G) alive2FTerminal(device, false);
        return false;
    }
    // Install recovery only after all original attach/preinit DMA work.
    if (!drain2MSetup()) {
        XYLog("KGP_DRAIN_2M setup failed=0x%x\n", fDrain2MStats[17]);
        detach(device);
        if (captureAttach2G) alive2FTerminal(device, false);
        return false;
    }
    if (captureAttach2G) alive2FTerminal(device, true);
    return true;
}

void ItlIwx::
detach(IOPCIDevice *device)
{
    drain2MRemove(); // fence deferred callbacks before any queue/backing free
    tx2IStop(3);
    flow2J(3, 0); flow2JPublish();
    struct _ifnet *ifp = &com.sc_ic.ic_ac.ac_if;
    struct iwx_softc *sc = &com;
    const bool timeDetach2H = alive2FOwned();
    if (timeDetach2H) { fDetach2H[0] = 1; fDetach2H[1] = time2GNow(); }
    
    for (int txq_i = 0; txq_i < nitems(sc->txq); txq_i++)
        iwx_free_tx_ring(sc, &sc->txq[txq_i]);
    if (timeDetach2H) fDetach2H[2] = time2GNow();
    iwx_free_rx_ring(sc, &sc->rxq);
    if (timeDetach2H) fDetach2H[3] = time2GNow();
    iwx_dma_contig_free(&sc->ict_dma);
    if (timeDetach2H) fDetach2H[4] = time2GNow();
    iwx_dma_contig_free(&com.ctxt_info_dma);
    if (timeDetach2H) fDetach2H[5] = time2GNow();
    ieee80211_ifdetach(ifp);
    if (timeDetach2H) fDetach2H[6] = time2GNow();
    taskq_destroy(systq);
    if (timeDetach2H) fDetach2H[7] = time2GNow();
    taskq_destroy(com.sc_nswq);
    if (timeDetach2H) fDetach2H[8] = time2GNow();
    releaseAll();
    if (timeDetach2H) fDetach2H[9] = time2GNow();
}

void ItlIwx::
releaseAll()
{
    drain2MRemove();
    pci_intr_handle *intrHandler = com.ih;
    
    if (intrHandler) {
        if (intrHandler->intr && intrHandler->workloop) {
//            intrHandler->intr->disable();
            intrHandler->workloop->removeEventSource(intrHandler->intr);
            intrHandler->intr->release();
        }
        intrHandler->intr = NULL;
        intrHandler->workloop = NULL;
        intrHandler->arg = NULL;
        intrHandler->dev = NULL;
        intrHandler->func = NULL;
        intrHandler->release();
        com.ih = NULL;
    }
    pci.pa_tag = NULL;
    pci.workloop = NULL;
}

void ItlIwx::free()
{
    drain2MRemove();
    if (fDrain2MLock) { IOSimpleLockFree(fDrain2MLock); fDrain2MLock = nullptr; }
    tx2IFree();
    cmd2KFree();
    XYLog("%s\n", __FUNCTION__);
    super::free();
}

