/* MAC1TXPF-20261028: isolated, read-only MAC1 station/queue preflight.
 * No ADD_STA, SCD_QUEUE_CFG, firmware read, TX reroute, or queue allocation.
 * Only existing task and TX paths publish observed state to IORegistry.
 */
/* MAC1-LINK-V0-20261101: read-only admission precursor, Debug only.
 * It does NOT validate an AWDL peer, create a node/station, or route TX.
 * The RX "last peer" counters are matched against an outgoing destination
 * cache, not an independently authorized peer roster. They CANNOT clear
 * PEER_UNVERIFIED. Do not store/publish peer or local MAC addresses here.
 */
#define MAC1_LINK_V0_FW_WRITES_ALLOWED 0
static_assert(MAC1_LINK_V0_FW_WRITES_ALLOWED == 0,
              "MAC1-LINK-V0 must never issue firmware commands");
static constexpr UInt32 kMac1LinkV0NoStableLocal = 1U;
static constexpr UInt32 kMac1LinkV0PeerUnverified = 2U;
static constexpr UInt32 kMac1LinkV0StaUnverified = 4U;
static constexpr UInt32 kMac1LinkV0QueueUnverified = 8U;
static constexpr UInt32 kMac1LinkV0RetirementUnverified = 16U;
#ifdef DEBUG
static volatile UInt32 gMac1LinkV0CandidateCount = 0U;
static volatile UInt32 gMac1LinkV0LastBlockMask = 0xffffffffU;
static volatile UInt32 gMac1LinkV0LocalSourceMatches = 0U;
#endif

static volatile UInt32 gMac1TxPfSamples = 0;
static volatile UInt32 gMac1TxPfDataFrames = 0;
static volatile UInt32 gMac1TxPfLastQid = 0xffffffffU;
static volatile UInt32 gMac1TxPfInfraNode = 0;
static void
mac1TxPreflightPublish(struct iwx_softc *sc, IOEthernetController *controller)
{
    if (sc == nullptr || controller == nullptr)
        return;
    const UInt32 samples = __atomic_add_fetch(
        &gMac1TxPfSamples, (UInt32)1, __ATOMIC_RELAXED);
    const int infraQid = sc->first_data_qid;
    const bool validInfraQid = infraQid >= 0 &&
        (unsigned)infraQid < (unsigned)nitems(sc->txq);
    const bool hostRingPrepared = validInfraQid &&
        sc->txq[infraQid].ring_count > 0 &&
        sc->txq[infraQid].desc != nullptr;
    controller->setProperty("AIRPLAYMAC1TXPFVersion", (unsigned long long)1, 8);
    controller->setProperty("AIRPLAYMAC1TXPFSamples", (unsigned long long)samples, 32);
    controller->setProperty("AIRPLAYMAC1TXPFMac1Valid", (unsigned long long)(gAirplayP2PMac1Valid != 0), 8);
    controller->setProperty("AIRPLAYMAC1TXPFSessionActive", (unsigned long long)(gAirplayP2PSessionActive != 0), 8);
    controller->setProperty("AIRPLAYMAC1TXPFInfraQidValid", (unsigned long long)validInfraQid, 8);
    controller->setProperty("AIRPLAYMAC1TXPFInfraQid", (unsigned long long)(UInt32)infraQid, 32);
    controller->setProperty("AIRPLAYMAC1TXPFInfraHostRingPrepared", (unsigned long long)hostRingPrepared, 8);
    controller->setProperty("AIRPLAYMAC1TXPFDataFrames", (unsigned long long)__atomic_load_n(&gMac1TxPfDataFrames, __ATOMIC_RELAXED), 32);
    controller->setProperty("AIRPLAYMAC1TXPFLastDataQid", (unsigned long long)__atomic_load_n(&gMac1TxPfLastQid, __ATOMIC_RELAXED), 32);
    controller->setProperty("AIRPLAYMAC1TXPFLastDataInfraNode", (unsigned long long)__atomic_load_n(&gMac1TxPfInfraNode, __ATOMIC_RELAXED), 8);
    controller->setProperty("AIRPLAYMAC1TXPFStationWritesEnabled", (unsigned long long)0, 8);
    controller->setProperty("AIRPLAYMAC1TXPFQueueWritesEnabled", (unsigned long long)0, 8);
    controller->setProperty("AIRPLAYMAC1TXPFRerouteEnabled", (unsigned long long)0, 8);
#ifdef DEBUG
    /* V38: V0 still requires an outgoing unicast; V1 RX and V2
     * preparation counters publish independently of that gate.
     * Observation only; no MAC addresses, FW commands or TX changes. */
    controller->setProperty("AIRPLAYDIAGMac1LinkV38Version", (unsigned long long)38U, 8);
    if (__atomic_load_n(&gMac1LinkV0CandidateCount, __ATOMIC_RELAXED)) {
        controller->setProperty("AIRPLAYDIAGMac1LinkV0Candidates",
            (unsigned long long)__atomic_load_n(
                &gMac1LinkV0CandidateCount, __ATOMIC_RELAXED), 32);
        controller->setProperty("AIRPLAYDIAGMac1LinkV0LastBlockMask",
            (unsigned long long)__atomic_load_n(
                &gMac1LinkV0LastBlockMask, __ATOMIC_RELAXED), 32);
        controller->setProperty("AIRPLAYDIAGMac1LinkV0LocalSourceMatches",
            (unsigned long long)__atomic_load_n(
                &gMac1LinkV0LocalSourceMatches, __ATOMIC_RELAXED), 8);
        controller->setProperty("AIRPLAYDIAGMac1LinkV0Ready",
            (unsigned long long)0U, 8);
    }
        controller->setProperty("AIRPLAYDIAGMac1LinkV1RXObserved",
            (unsigned long long)__atomic_load_n(&gMac1LinkV1Observed, __ATOMIC_RELAXED), 32);
        controller->setProperty("AIRPLAYDIAGMac1LinkV1EligibleMgmt",
            (unsigned long long)__atomic_load_n(&gMac1LinkV1EligibleMgmt, __ATOMIC_RELAXED), 32);
        controller->setProperty("AIRPLAYDIAGMac1LinkV1EligibleData",
            (unsigned long long)__atomic_load_n(&gMac1LinkV1EligibleData, __ATOMIC_RELAXED), 32);
        controller->setProperty("AIRPLAYDIAGMac1LinkV1EligibleMissingCtxBit",
            (unsigned long long)__atomic_load_n(&gMac1LinkV1EligibleMissingCtxBit, __ATOMIC_RELAXED), 32);
        controller->setProperty("AIRPLAYDIAGMac1LinkV1PeerConflicts",
            (unsigned long long)__atomic_load_n(&gMac1LinkV1Conflicts, __ATOMIC_RELAXED), 32);
        controller->setProperty("AIRPLAYDIAGMac1LinkV1LastTXPeerMatch",
            (unsigned long long)__atomic_load_n(&gMac1LinkV1LastTXMatch, __ATOMIC_RELAXED), 8);
        controller->setProperty("AIRPLAYDIAGMac1LinkV1Ready", (unsigned long long)0U, 8);
        controller->setProperty("AIRPLAYDIAGMac1LinkV2Candidates",
            (unsigned long long)__atomic_load_n(&gMac1LinkV2Candidates, __ATOMIC_RELAXED), 32);
        controller->setProperty("AIRPLAYDIAGMac1LinkV2Prepared",
            (unsigned long long)__atomic_load_n(&gMac1LinkV2Prepared, __ATOMIC_RELAXED), 32);
        controller->setProperty("AIRPLAYDIAGMac1LinkV2LastReject",
            (unsigned long long)__atomic_load_n(&gMac1LinkV2LastReject, __ATOMIC_RELAXED), 32);
        controller->setProperty("AIRPLAYDIAGMac1LinkV2Ready", (unsigned long long)0U, 8);
    /* Also published on the existing NS-worker cadence even without TX. */
    if (airplayTxCtxV1DiagOn()) mac1PcPublish(controller,(UInt32)sc->sc_generation);
#endif
}

/* MAC1TXS1-20261028: NEW experiment, existing source preserved.
 * Station registration test: ADD -> REMOVE immediately, no TX queue.
 * Two gates: compile-time hard interlock AND explicit boot argument.
 * Hard interlock is intentionally 0. Do not flip before code review.
 * Queue remains preparation-only. No SCD_QUEUE_CFG commands added.
 */
#define MAC1TX_S1_FIRMWARE_WRITE_REVIEWED 0
static_assert(sizeof(struct iwx_tx_queue_cfg_cmd) == 24, "MAC1TXS1: unexpected v2 queue CMD ABI");
static_assert(sizeof(struct iwx_tx_queue_cfg_rsp) == 8, "MAC1TXS1: unexpected v2 queue RSP ABI");
static const UInt32 kMac1TxS1StationId = 3U; /* legacy DATASTA2 owns 3; mutually excluded */
#ifdef DEBUG
/* V86: request/reply HOST lineage only. This is NOT firmware queue ownership.
 * One bit per missing prerequisite: 0=submit claim, 1=send permission,
 * 2=command transport success, 3=matching response envelope,
 * 4=generation continuity, 5=requested STA3, 6=requested management TID,
 * 7=candidate QID in range, 8=no currently observed stock conflict.
 * Zero means correlated HOST evidence, never exclusive firmware ownership. */
/* V87: one atomic 64-bit HOST witness avoids torn generation/mask/seen.
 * Layout: bits 41:10 = captured generation, 9:1 = rejection mask, 0 = valid.
 * This proves only the coherence of host diagnostics at a read instant;
 * it NEVER proves command/DMA quiescence or firmware queue ownership. */
struct Mac1V87HostLineage {
    UInt32 generation, rejectMask, seen, generationStable;
};
static uint64_t mac1V87PackHostLineage(UInt32 generation, UInt32 mask) {
    const UInt32 safeMask = (mask & ~0x1ffU) ? 0x1ffU : mask;
    return (uint64_t(generation) << 10) | (uint64_t(safeMask) << 1) | 1ULL;
}
static Mac1V87HostLineage mac1V87DecodeHostLineage(
    uint64_t word, UInt32 generationBefore, UInt32 generationAfter) {
    const UInt32 recorded = (UInt32)(word >> 10);
    const bool stable = generationBefore != 0U &&
        generationBefore == generationAfter;
    const bool current = stable && (word & 1ULL) != 0ULL &&
        recorded == generationBefore;
    const Mac1V87HostLineage snapshot = {
        recorded, current ? (UInt32)((word >> 1) & 0x1ffULL) : 0x1ffU,
        current ? 1U : 0U, stable ? 1U : 0U
    };
    return snapshot;
}
/* V88 host-only interpretation of the V87 atomic word.
 * State: 0=no witness, 1=unstable generation, 2=stale generation,
 * 3=current host rejected, 4=current host clear (NOT firmware ownership).
 * Missing count=0xffffffff, first rejected=9: no current verdict.
 * Reject bit indices 0..8 are the nine V86 host prerequisites. */
struct Mac1V88Readout { UInt32 state, missingCount, firstRejected; };
static Mac1V88Readout mac1V88Explain(uint64_t word, UInt32 before, UInt32 after,
    const Mac1V87HostLineage &trace) {
    if (!(word & 1ULL)) return {0U, 0xffffffffU, 9U};
    if (before == 0U || before != after) return {1U, 0xffffffffU, 9U};
    if ((UInt32)(word >> 10) != before) return {2U, 0xffffffffU, 9U};
    if (!trace.seen) return {1U, 0xffffffffU, 9U};
    UInt32 mask = trace.rejectMask & 0x1ffU, count = 0U, first = 9U;
    for (UInt32 bit = 0U; bit < 9U; ++bit)
        if (mask & (1U << bit)) {
            if (first == 9U) first = bit;
            ++count;
        }
    return {mask ? 3U : 4U, count, first};
}
static UInt32 mac1V86HostTraceRejectMask(bool claimed, bool sendPermitted,
    bool transportOK, bool acceptedShape, bool sameGeneration,
    bool station3, bool mgmtTid, bool qidInRange, bool noKnownConflict) {
    UInt32 m=0U;
    if (!claimed) m |= 1U << 0;
    if (!sendPermitted) m |= 1U << 1;
    if (!transportOK) m |= 1U << 2;
    if (!acceptedShape) m |= 1U << 3;
    if (!sameGeneration) m |= 1U << 4;
    if (!station3) m |= 1U << 5;
    if (!mgmtTid) m |= 1U << 6;
    if (!qidInRange) m |= 1U << 7;
    if (!noKnownConflict) m |= 1U << 8;
    return m;
}
/* No S7 observation is deliberately distinguishable from a clean trace. */
/* Single atomic witness; no independent multi-field publication writer. */
static uint64_t gMac1TxS7V87HostTraceWord = 0ULL;
#endif
static volatile UInt32 gMac1TxS1Attempts = 0;
static volatile UInt32 gMac1TxS1AddTransport = 0xffffffffU;
static volatile UInt32 gMac1TxS1AddStatus = 0xffffffffU;
static volatile UInt32 gMac1TxS1RemoveTransport = 0xffffffffU;
static volatile UInt32 gMac1TxS1BindingValidated = 0;
static volatile UInt32 gMac1TxS1InterlockBlocked = 0;
static volatile UInt32 gMac1TxS1PreflightReady = 0;
static volatile UInt32 gMac1TxS1QueueCmdBytes = 0;
static volatile UInt32 gMac1TxS1QueueRspBytes = 0;
static volatile UInt32 gMac1TxS1HostRingCount = 0;
