/* MAC1TXS7-20261028: experimental MAC1 management queue, explicit opt-in.
 * This is a one-shot firmware queue-ALLOCATION PROBE only, not AWDL data TX.
 * Requires a separate opt-in binary/source review before enabling the gate.
 * Do not reuse infrastructure TX rings or the sc_tvqm_ring allocator.
 * On ANY attempted firmware queue enable, keep all DMA pinned (quarantine)
 * until a verified device reset / safe release review. Never automatically
 * destroy DMA after just an ADD/REMOVE transport ACK.
 */
/* MAC1TXS7-ONESHOT-20261028: ISOLATED, OPT-IN, FIRMWARE-WRITING BUILD.
 * This IS NOT live queue retirement. A single enable request is allowed,
 * never queued packet TX. The associated station remains registered until
 * firmware reset. Experimental DMA is quarantined until positive bus-master
 * stop AND processor reset, never an ACK, timeout or software generation.
 * DO NOT stage without intentional double-bootarg opt-in and rollback plan.
 */
/* MAC1TXS7-MIN128-20261028: AX210-specific minimum queue capacity only.
 * Intel iwlwifi AX210 min_txq_size=128; the previous S7 one-shot
 * requested 16, although generic IWL_MGMT_QUEUE_SIZE is 16.
 * Hypothesis: undersized ring caused FW response flags=1.
 * STILL one-shot; station/queue commands need both existing boot args.
 */
#define MAC1TX_S7_PROBE_QUEUE_DESCRIPTORS 128
static_assert(MAC1TX_S7_PROBE_QUEUE_DESCRIPTORS >= 128 &&
              MAC1TX_S7_PROBE_QUEUE_DESCRIPTORS <= 256 &&
              (MAC1TX_S7_PROBE_QUEUE_DESCRIPTORS &
               (MAC1TX_S7_PROBE_QUEUE_DESCRIPTORS - 1)) == 0,
              "MAC1TXS7: AX210 ring count must be supported power of two");
#define MAC1TX_S7_FW_QUEUE_WRITES_APPROVED 1
/* V19 requires a second deliberate, reviewed opt-in; never arm on normal boot. */
#define MAC1_S3_V19_V3_FW_SEND_ALLOWED 0
static_assert(MAC1_S3_V19_V3_FW_SEND_ALLOWED == 0,
              "V19 is compile-only; no S3 v3 firmware submission");
/* V30: one-shot legacy-v2 queue ADD, ONLY with both S6/S7 opt-in boot args.
 * No unicast data TX, no QID adoption, no live DMA retirement.
 * Outcome uncertain or collision => quarantine and no retry.
 */
#define MAC1_S3_V29_V2_FW_SEND_ALLOWED 1
static_assert(MAC1_S3_V29_V2_FW_SEND_ALLOWED == 1,
              "V30 queue probe requires legacy-v2 send gate");
#define MAC1TX_S7_TX_REROUTE_APPROVED 0
#define MAC1TX_S7_FW_QUEUE_RETIRED_VERIFIED 0
#define MAC1TX_S7_RESET_ONLY_CONTAINMENT_REVIEWED 1
/* Two explicit choices: verified live retirement OR reviewed reset-only
 * containment. The latter NEVER authorizes reusing a queue in a live FW. */
static_assert(!MAC1TX_S7_FW_QUEUE_WRITES_APPROVED ||
              (MAC1TX_S7_FW_QUEUE_RETIRED_VERIFIED ||
               MAC1TX_S7_RESET_ONLY_CONTAINMENT_REVIEWED),
              "MAC1TXS7: enable requires a reviewed containment path");
static_assert(MAC1TX_S7_TX_REROUTE_APPROVED == 0,
              "MAC1TXS7: packet TX forbidden in one-shot test");
static bool mac1TxS7Requested(void)
{
    static int cached = -1;
    if (cached < 0) {
        int unused = 0;
        cached = PE_parse_boot_argn("-awdlmac1txq7", &unused,
                                    sizeof(unused)) ? 1 : 0;
    }
    return cached == 1;
}
struct Mac1TxS7Probe {
    UInt32 requested, attempted, blocked, generation;
    UInt32 phase, allocErr, sendErr, replyFlags, candidateQid;
    UInt32 collision, mayReferenceDma, dmaRetained, disableAttempted;
    UInt32 stationRemovalHeld;
};
static Mac1TxS7Probe gMac1TxS7 = {
    0, 0, 0, 0xffffffffU, 0, 0, 0xffffffffU,
    0xffffffffU, 0xffffffffU, 0, 0, 0, 0
};
/* Pinned once a firmware command could reference it. Never published as an
 * active host sc->txq[] entry or reused for infrastructure transmissions. */
static struct iwx_tx_ring *gMac1TxS7Sandbox = nullptr;
/* MAC1TXS7-RESET-RETIRE-20261028: never confuse a FW response with
 * quiescence of a DMA address. Sandbox belongs to one softc only.
 * Count deferrals instead of freeing DMA while a command can still run.
 */
static struct iwx_softc *gMac1TxS7SandboxOwner = nullptr;
static UInt32 gMac1TxS7CmdInFlight = 0;
/* The in-flight bit is the earliest NO-FREE fence. OwnerReady is
 * published only AFTER the owner and sandbox pointers exist. RX
 * must observe OwnerReady with acquire semantics before reading them. */
static UInt32 gMac1TxS7OwnerReady = 0U;
static mac1s3replyslot::Claim gMac1S3ReplySlotClaim = {};
static mac1s3submitfence::Fence gMac1S3SubmitFence = {};
static UInt32 gMac1S3FenceRejected = 0;
static UInt32 gMac1S3FenceSkippedSend = 0;
static UInt32 gMac1S3FenceRecoveryBusy = 0;
/* noteStop only operates on this atomic fence. It never releases DMA. */
static void mac1S3SubmitFenceNoteStop(void) {
    gMac1S3SubmitFence.noteStop();
    /* V27: an in-progress stop forbids treating any later RX packet as the
     * response to our prior S3 command. Sandbox DMA is NOT released here. */
    gMac1S3ReplySlotClaim.noteStop();
}
/* V31: only the verified positive-reset path stages evidence, while the
 * real PC1 recovery gate is the ONLY place allowed to reopen this fence. */
static uint64_t mac1S3FenceStopSerial(void) {
    return gMac1S3SubmitFence.stopSerial();
}
static void mac1S3FenceResetVerified(struct iwx_softc *sc,
                                     uint64_t serial, uint32_t epoch) {
    gMac1S3SubmitFence.resetVerified(sc, serial, epoch);
}
static void mac1S3FenceRecoveryPassed(struct iwx_softc *sc, uint32_t epoch) {
    if (!sc || gMac1TxS7Sandbox != nullptr ||
        __atomic_load_n(&gMac1TxS7CmdInFlight, __ATOMIC_ACQUIRE) != 0U ||
        __atomic_load_n(&gMac1TxS7OwnerReady, __ATOMIC_ACQUIRE) != 0U ||
        __atomic_load_n(&gMac1TxS7SandboxOwner, __ATOMIC_ACQUIRE) != nullptr ||
        gMac1S3ReplySlotClaim.armed() || gMac1S3SubmitFence.claimed()) {
        ++gMac1S3FenceRecoveryBusy;
        return; /* pinned/unknown: preserve stop fence and all DMA */
    }
    (void)gMac1S3SubmitFence.recoverAfterPC1(sc, epoch);
}

/* V81: read existing S7 guards, using the SAME predicates as the
 * recovery fence. Observational only; no locks, waits or modifications. */
static UInt32 v81S7BusyMask(void) {
    UInt32 busy = 0U;
    if (gMac1TxS7Sandbox != nullptr) busy |= (1U << 0);
    if (__atomic_load_n(&gMac1TxS7CmdInFlight, __ATOMIC_ACQUIRE) != 0U)
        busy |= (1U << 1);
    if (__atomic_load_n(&gMac1TxS7OwnerReady, __ATOMIC_ACQUIRE) != 0U ||
        __atomic_load_n(&gMac1TxS7SandboxOwner, __ATOMIC_ACQUIRE) != nullptr)
        busy |= (1U << 2);
    if (gMac1S3ReplySlotClaim.armed()) busy |= (1U << 3);
    if (gMac1S3SubmitFence.claimed()) busy |= (1U << 4);
    return busy;
}

/* Exact S7 claim remains mandatory at the command handoff. */
static bool mac1S3SubmitFenceCanPublish(void) {
    return gMac1S3SubmitFence.maySend() &&
        __atomic_load_n(&gMac1TxS7CmdInFlight, __ATOMIC_ACQUIRE) != 0U;
}
static UInt32 gMac1TxS7MasterStopReleases = 0;
static UInt32 gMac1TxS7MasterStopDeferrals = 0;
static UInt32 gMac1TxS7ReplyWritePointer = 0xffffffffU;
/* S7 corrected classifier: raw firmware flags remain DIAGNOSTIC ONLY.
 * A set flag is documented as failure in the API header, BUT this AX210
 * driver observed flags=1 in two working infrastructure queue paths.
 * Consequently neither flag value, nor an unobserved QID, establishes success.
 * Preallocated host-ring memory is not a firmware owner. No TX authorization.
 * Values: 1=out of bounds; 2=fixed owner; 3=dynamic owner; 4=infra mapping;
 * 5=active TID mapping; 6=host queued work; 7=unverified candidate.
 */
static UInt32 mac1TxS7ClassifyCandidate(
    struct iwx_softc *sc, UInt32 q)
{
    if (!sc || q >= (UInt32)nitems(sc->txq) || q >= 32U) return 1U;
    const UInt32 bit = 1U << q;
    if (__atomic_load_n(&gS7StockFixedMask, __ATOMIC_ACQUIRE) & bit) return 2U;
    if (__atomic_load_n(&gS7StockDynamicMask, __ATOMIC_ACQUIRE) & bit) return 3U;
    if ((int)q == sc->first_data_qid) return 4U;
    for (unsigned tid = 0; tid < nitems(sc->sc_tid_data); ++tid) {
        if ((int)q == sc->sc_tid_data[tid].qid) return 5U;
    }
    if (sc->txq[q].queued != 0) return 6U;
    return 7U; /* UNKNOWN ownership, never proof of a free queue */
}
static UInt32 gMac1TxS7CandidateAudit = 0U;
static UInt32 gMac1TxS7CandidateOwnershipVerified = 0U;
/* MAC1TX-S7-OWNER-ONESHOT-20261028: safety preflight for active queue
 * experiment: ensure the instrumentation has witnessed ordinary infrastructure
 * queues THIS FW generation. These are necessary observations, NOT proof that
 * the ledger is exhaustive, the candidate is free, or MAC1 TX is ready.
 * 0x3f means every conservative precondition was observed.
 */
static UInt32 gMac1TxS7OwnerProbePreflight = 0U;
static UInt32 mac1TxS7OwnerProbePreflight(struct iwx_softc *sc)
{
    if (!sc) return 0U;
    const UInt32 fixed = __atomic_load_n(&gS7StockFixedMask, __ATOMIC_ACQUIRE);
    const UInt32 dynamic = __atomic_load_n(&gS7StockDynamicMask, __ATOMIC_ACQUIRE);
    UInt32 bits=0U;
    if (__atomic_load_n(&gS7StockLastGeneration, __ATOMIC_ACQUIRE) ==
        (UInt32)sc->sc_generation) bits |= 1U;
    if (fixed) bits |= 2U;
    if (dynamic) bits |= 4U;
    if (__atomic_load_n(&gS7StockUntracked, __ATOMIC_ACQUIRE) == 0U) bits |= 8U;
    if ((fixed & dynamic) == 0U) bits |= 16U;
    if (!gMac1TxS7Sandbox &&
        __atomic_load_n(&gMac1TxS7CmdInFlight, __ATOMIC_ACQUIRE) == 0U)
        bits |= 32U;
    return bits;
}
static UInt32 gMac1TxS7ReplyReserved = 0xffffffffU;
static UInt32 gMac1TxS7ReplyPayloadLen = 0xffffffffU;
static UInt32 gMac1TxS7ReplyGroup = 0xffffffffU;
static UInt32 gMac1TxS7ReplyIdentityV1 = 0xffffffffU;
static UInt32 gMac1TxS7ReplySameGeneration = 0U;
static UInt32 mac1TxS7OwnershipSelfTest(void)
{
    /* Pure synthetic classifier, independent of hardware/RX/task timing. */
    const UInt32 fixed=1U << 1;
    const UInt32 dynamic=1U << 2;
    UInt32 result=0;
    if ((fixed & (1U << 1)) != 0) result |= 1U;
    if ((dynamic & (1U << 2)) != 0) result |= 2U;
    if (((fixed | dynamic) & (1U << 4)) == 0) result |= 4U;
    if (sizeof(struct iwx_tx_queue_cfg_rsp) == 8) result |= 8U;
    /* No test is allowed to infer 'free' from an absent owner bit. */
    const UInt32 unknown=7U;
    if (unknown != 0U && unknown != 4U) result |= 16U;
    return result;
}


/* Called only from the positive AX210 master-stop/reset branch. Transfers
 * the quarantined pointer to iwx_stop_device, which owns the DMA allocator.
 * No member-method access outside ItlIwx is needed.
 */
static bool mac1TxS7TakeResetRetiredSandbox(
    struct iwx_softc *sc, struct iwx_tx_ring **out)
{
    if (!out) return false;
    *out = nullptr;
    if (!gMac1TxS7Sandbox) return false;
    /* V28: stop must not reclaim S7 DMA in the narrow interval
     * after the synchronous sender clears CmdInFlight but before its
     * submission fence is released. A live RX slot claim also blocks.
     * The caller has ALREADY verified master stop + processor reset;
     * this policy is an additional necessary check, not proof of either.
     */
    const uint32_t retireBlockedV28 = mac1s3retire::blockers(
        true,
        __atomic_load_n(&gMac1TxS7SandboxOwner, __ATOMIC_ACQUIRE) == sc,
        __atomic_load_n(&gMac1TxS7CmdInFlight, __ATOMIC_ACQUIRE) != 0U,
        gMac1S3SubmitFence.claimed(),
        gMac1S3ReplySlotClaim.armed());
    if (retireBlockedV28 != 0U) {
        ++gMac1TxS7MasterStopDeferrals;
        return false;
    }
    __atomic_store_n(&gMac1TxS7OwnerReady, 0U, __ATOMIC_RELEASE);
    *out = gMac1TxS7Sandbox;
    gMac1TxS7Sandbox = nullptr;
    __atomic_store_n(&gMac1TxS7SandboxOwner,
                     (struct iwx_softc *)nullptr, __ATOMIC_RELEASE);
    gMac1TxS7.mayReferenceDma = 0;
    gMac1TxS7.dmaRetained = 0;
    ++gMac1TxS7MasterStopReleases;
    /* Do not erase sticky one-shot / station quarantine history. */
    return true;
}
/* MAC1TXS7-FLUSH-ISOLATION-20261028:
 * Unlike iwx_flush_sta_tids(), this audit NEVER advances a host TX ring.
 * The old helper uses FW-reported QIDs to access sc->txq[], which MUST NOT
 * be done on a dynamically assigned experimental queue. The audit operates
 * on copied reply metadata only. It does not issue firmware commands.
 * A match establishes reply SHAPE, NOT queue disable, transport drain,
 * firmware ownership, or authorization to free DMA.
 */
static UInt32 mac1TxS7AuditFlushMetadata(
    const struct iwx_tx_path_flush_cmd_rsp *r, UInt16 expectedQid)
{
    if (!r || expectedQid == (UInt16)0xffff) return 1U;
    if (le16toh(r->sta_id) != (UInt16)kMac1TxS1StationId) return 2U;
    const UInt32 n = le16toh(r->num_flushed_queues);
    if (n > IWX_TX_FLUSH_QUEUE_RSP) return 4U;
    /* A zero-entry reply is ambiguous, never retirement proof. */
    if (n != 1U) return 8U;
    if (le16toh(r->queues[0].queue_num) != expectedQid) return 16U;
    if (le16toh(r->queues[0].tid) != (UInt16)IWX_MGMT_TID) return 32U;
    return 0U;  /* Metadata matches only; DMA is STILL quarantined. */
}
static UInt32 mac1TxS7FlushAuditSelfTest(void)
{
    struct iwx_tx_path_flush_cmd_rsp r = {};
    UInt32 result = 0U;
    r.sta_id = htole16((UInt16)kMac1TxS1StationId);
    r.num_flushed_queues = htole16(1);
    r.queues[0].queue_num = htole16(7);
    r.queues[0].tid = htole16((UInt16)IWX_MGMT_TID);
    if (mac1TxS7AuditFlushMetadata(&r, 7) == 0) result |= 1U;
    r.sta_id = htole16(0);
    if (mac1TxS7AuditFlushMetadata(&r, 7) == 2U) result |= 2U;
    r.sta_id = htole16((UInt16)kMac1TxS1StationId);
    r.num_flushed_queues = htole16(0);
    if (mac1TxS7AuditFlushMetadata(&r, 7) == 8U) result |= 4U;
    r.num_flushed_queues = htole16(1);
    if (mac1TxS7AuditFlushMetadata(&r, 8) == 16U) result |= 8U;
    r.queues[0].tid = htole16(1);
    if (mac1TxS7AuditFlushMetadata(&r, 7) == 32U) result |= 16U;
    return result;
}
