                                            const UInt32 bss = __atomic_load_n(&s->nodeIsBss, __ATOMIC_RELAXED);
                                            const UInt32 same = __atomic_load_n(&s->destEqualsLinkPeer, __ATOMIC_RELAXED);
                                            const UInt32 own = __atomic_load_n(&s->hostQueueOwnerValid, __ATOMIC_RELAXED);
                                            const UInt32 packed = __atomic_load_n(&s->hostOwnerStaTid, __ATOMIC_RELAXED);
                                            __atomic_store_n(&gAirplayTxCtxV1LastNodeIsBss, bss, __ATOMIC_RELAXED);
                                            __atomic_store_n(&gAirplayTxCtxV1LastDestEqLinkPeer, bss ? same : 2U, __ATOMIC_RELAXED);
                                            __atomic_store_n(&gAirplayTxCtxV1LastQueue, 1U, __ATOMIC_RELAXED);
