                                            __atomic_store_n(&gAirplayTxCtxV1LastOwnerSta, own ? ((packed >> 8) & 255U) : 255U, __ATOMIC_RELAXED);
                                            __atomic_store_n(&gAirplayTxCtxV1LastOwnerTid, own ? (packed & 255U) : 255U, __ATOMIC_RELAXED);
