                                            __atomic_store_n(&gAirplayTxCtxV1LastFwSta, IWX_TX_RES_GET_RA(raTid), __ATOMIC_RELAXED);
                                            __atomic_store_n(&gAirplayTxCtxV1LastFwTid, IWX_TX_RES_GET_TID(raTid), __ATOMIC_RELAXED);
                                            __atomic_store_n(&gAirplayTxCtxV1LastSessionAtSubmit,
                                                __atomic_load_n(&s->p2pActiveAtSubmit, __ATOMIC_RELAXED), __ATOMIC_RELAXED);
                                            __atomic_store_n(&gAirplayTxCtxV1LastStageChan,
                                                __atomic_load_n(&s->stageChannelAtSubmit, __ATOMIC_RELAXED), __ATOMIC_RELAXED);
                                            __atomic_store_n(&gAirplayTxCtxV1LastStageKnown,
                                                __atomic_load_n(&s->stageChannelKnown, __ATOMIC_RELAXED), __ATOMIC_RELAXED);
                                            __atomic_store_n(&gAirplayTxCtxV1LastInfraChan,
                                                __atomic_load_n(&s->infraChannelAtSubmit, __ATOMIC_RELAXED), __ATOMIC_RELAXED);
                                            __atomic_store_n(&gAirplayTxCtxV1LastStatus, (UInt32)v3st, __ATOMIC_RELAXED);
