                                        const UInt32 diagRaTid = (UInt32)tx_resp->ra_tid;
                                        const UInt32 diagStation = IWX_TX_RES_GET_RA(diagRaTid);
                                        const UInt32 diagTid = IWX_TX_RES_GET_TID(diagRaTid);
                                        __atomic_store_n(&gAwDiagV1RaTidRawLast, diagRaTid, __ATOMIC_RELAXED);
                                        __atomic_store_n(&gAwDiagV1StationLast, diagStation, __ATOMIC_RELAXED);
                                        __atomic_store_n(&gAwDiagV1TidLast, diagTid, __ATOMIC_RELAXED);
                                        if (diagStation == 0U)
                                            __atomic_fetch_add(&gAwDiagV1StationZero, 1U, __ATOMIC_RELAXED);
                                        else
                                            __atomic_fetch_add(&gAwDiagV1StationOther, 1U, __ATOMIC_RELAXED);
                                        const UInt32 noAck = (UInt32)tx_resp->failure_frame;
                                        const UInt32 mediaUs = (UInt32)le16toh(tx_resp->wireless_media_time);
                                        const struct iwx_tx_cmd_gen3 *v3doneCmd =
                                            (const struct iwx_tx_cmd_gen3 *)ring->cmd[t].data;
                                        const UInt32 frameLen = (UInt32)le16toh(v3doneCmd->len);
                                        __atomic_fetch_add(&gAwTxClassV3Q1UcastLongLimit, 1U, __ATOMIC_RELAXED);
