                            __atomic_fetch_add(&gAwTxClassV2SingleReclaim, 1U, __ATOMIC_RELAXED);
                        else
                            __atomic_fetch_add(&gAwTxClassV2MultiReclaim, 1U, __ATOMIC_RELAXED);
